import * as url from "url";
import config from "../config/app.json";

const { protocol, host, PORT } = config.server;

export default function serverPath(subRoute) {
	let route = String(subRoute || '');
	route = route.charAt(0) === '/' ?
	route : (route.trim() ? '/' + route : route);
	return (
		`${
			protocol.trim() === '' ?
			url.parse(String(window.location))
			.protocol : protocol
		}://${
			host.trim() === '' ?
			url.parse(
				String(window.location))
				.host.split(':')[0]:
				host.trim().split(':')[0]
		}:${
			PORT.trim() === '' ? ''
// 			url.parse(
// 				String(window.location))
// 				.host.split(':')[1]
			 	:PORT
		}${route}`.trim()
	);
}
