import { forwardRef, useEffect, useState, useLayoutEffect } from "react";
import * as React from 'react';
import {
    IconButton,
    OutlinedInput,
    InputLabel,
    InputAdornment,
    FormHelperText,
    FormControl
} from '@mui/material';
import Visibility from '@mui/icons-material/Visibility';
import VisibilityOff from '@mui/icons-material/VisibilityOff';
import ErrorIcon from '@mui/icons-material/Error';
import CheckIcon from "@mui/icons-material/Check";
import { Typography } from "@mui/material";
import { useData } from "../treatments/globalData";

function FieldContoller(props, ref) {
    const { screen, text:textContent } = useData();
    const { input:text } = textContent;
    const { 
        type, 
        label, 
        regExp, 
        helperText, 
        helperTextError, 
        helperTextSuccess, 
        checking, 
        icon,
        value:defaultValue,
        showPassword:outShowPassword,
        onShowPassword,
        onChange,
        multiline,
        ...otherPros } = props;
    const [values, setValues] = useState({
        type: type,
        content: defaultValue || '',
        error: null,
        checking: false,
        ...( type === 'password' ? 
        { showPassword: outShowPassword || false } : {})
    });
    const color = checking ? (values.error ? "error" : "primary") : "primary";
    const handleChange = (prop, value) => (event) => {
        if(typeof onChange === 'function' && event) onChange(event);
        setValues({
            ...values, 
            [prop]: value === undefined ? event.target.value : value,
        });
    }

    useLayoutEffect(()=> {
       const value = type === 'password' ?  values.content : values.content.trim();
       const isCorreted = (new RegExp(regExp)).test(value); 
       if(ref) ref.current = isCorreted ? value : null;
       if(!values.error && !isCorreted)
           handleChange('error', true)(null);
       if(values.error && isCorreted)
            handleChange('error', null)(null);
    });
   const typeFied = outShowPassword === undefined ? ( values.showPassword === undefined ? 
   values.type : (values.showPassword ? 'text' : values.type)
   ) : (outShowPassword ? 'text' : values.type);
    return (
        <FormControl color={color} {...otherPros} variant="outlined">
           { label && <InputLabel htmlFor={"outlined-adornment" + type }>{label}</InputLabel>}
            <OutlinedInput
            type={typeFied}
            value={values.content}
            onChange={handleChange('content')}
            multiline={multiline}
            rows={otherPros.rows}
            endAdornment={
              type === 'password' &&
               <InputAdornment position="end">
                    <IconButton
                        aria-label="toggle password visibility"
                        onClick={onShowPassword || handleChange('showPassword', !values.showPassword)}
                        onMouseDown={null}
                        edge="end"
                    >
                        { outShowPassword === undefined ? 
                           (values.showPassword ? <VisibilityOff /> : <Visibility />):
                           (outShowPassword ? <VisibilityOff /> : <Visibility />)
                        }
                </IconButton>
                </InputAdornment>
            }
            label={label}
            />
          { checking &&  
          <FormHelperText id="outlined-weight-helper-text">
                <Typography color={color} variant="caption" component="span"> 
                    {
                    icon && 
                         ( values.error ?  <ErrorIcon sx={{fontSize:"15px", position:'relative', top:2}} />
                          : <CheckIcon sx={{fontSize:"15px", position:'relative', top:2}} />) 
                    }  { 
                        Boolean(type === 'password' ? 
                        values.content : values.content.trim()
                        ) ?  (helperText ? helperText : (values.error ? helperTextError : helperTextSuccess)) : text.error.empty
                    } 
                </Typography>
           </FormHelperText>}
        </FormControl>
    );
}


export default forwardRef(FieldContoller);