import {
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    Button,
    Box,
    useTheme,
} from '@mui/material';
import { useRef, useState } from 'react';
import FormInputTheme from '../config/FormInputTheme';
import getFileExtension, { getName } from '../services/getFileExtension';
import TextFieldController from './TextFieldController';
import Paper from './Paper';

export default function FormFileNav (props) {
    const { file, labelAction, action } = props;
    const theme = useTheme();
    const color = theme.palette.mode === 'dark' ? 'inherit' : 'primary';
    const newFileName = useRef(file && getName(file.name));
    const [checking, setChecking] = useState(false);
    const extension = file && getFileExtension(file.name);
    return (
        <FormInputTheme>
            <Dialog 
                open={!!file}
            >
                <DialogTitle>
                    Fichier
                </DialogTitle>
                <DialogContent
                    sx={{width: 340}}
                >
                    <Box
                        sx={{
                            display: 'flex', 
                            justifyContent: 'center',
                            alignItems: 'center',
                            width: '100%',
                            flex: 1,
                            position: 'relative',
                            overflow: 'hidden',
                            bgcolor: `${theme.palette.background.paper}`,
                            mb:1,
                        }}
                    >
                        <Box
                            sx={{
                                height: '100%',
                                width: '100%',
                                zIndex: 10000,
                                position: 'absolute',
                                top: 0,
                                left: 0,
                            }}
                        />
                        <Paper
                            ext={extension}
                            label={file && file.name}
                            noteStyle={{
                                borderColor: `#fff ${theme.palette.background.paper} #bbb #ddd`,
                            }}
                        />
                    </Box>
                    <TextFieldController
                        margin="dense"
                        size="small"
                        type="text"
                        fullWidth
                        label="Renommer le fichier"
                        defaultValue={file && 
                            (
                                newFileName.current || 
                                getName(file.name))
                            }
                        regExp={".+"}
                        ref={newFileName}
                        checking={checking}
                    />      
                </DialogContent>
                <DialogActions>
                    <Button
                        children="annuler"
                        onClick={props.onClose}
                        color={color}
                        size="small"
                    />
                    <Button
                        onClick={ event => {
                            if(!newFileName.current)
                                setChecking(true)
                            else {
                                setChecking(false);
                                if(typeof action === 'function') 
                                    action(event, 
                                        file && 
                                        new File([file],
                                            newFileName.current + '.' +
                                            extension,
                                            {
                                                type: file.type,
                                            }
                                    ));
                                if(typeof props.onClose === 'function')
                                    props.onClose();
                            }
                        }}
                        variant="outlined"
                        color={color}
                        size="small"
                    >
                    {labelAction}
                    </Button>
                </DialogActions>
            </Dialog>
        </FormInputTheme>
    );
}
