import {Box, Typography, Modal, List, ListItem, ListItemIcon, ListItemText, Divider, CardActions, Button} from '@mui/material';
import LocalSeeIcon  from '@mui/icons-material/LocalSee';
import VideocamIcon  from '@mui/icons-material/Videocam';
import AudiotrackIcon  from '@mui/icons-material/Audiotrack';
import ArticleIcon  from '@mui/icons-material/Article';
import CalendarTodayIcon from '@mui/icons-material/CalendarToday';
import { forwardRef } from 'react';
import fileExtensionBase from '../config/fileExtensionBase';
import { getFileExtension, getFileName } from '../treatments/getFileExtension';
import formatDate from '../treatments/formatDate';
import ShortTextIcon from '@mui/icons-material/ShortText';
import PerfectScrollbar from 'react-perfect-scrollbar';

function FileDetail(props, ref) {
    const{ anchorEl, date, onClose, open, name } = props;
    const formats = [
        { label: 'photo', title: 'format images', icon: <LocalSeeIcon/> },
        { label: 'video', title: 'format videos', icon: <VideocamIcon/> },
        { label: 'audio', title: 'format audios', icon: <AudiotrackIcon/> },
        { label: 'doc', title: 'format documents', icon: <ArticleIcon/> },
        //{ label: 'video', title: 'format inconnu', icon: <QuizIcon/> }   
    ];
    return (
        <Box 
            //container={() => ref.current}
            component={Modal} 
            onClose={onClose} 
            open={open}
        >
        <Box sx={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            bgcolor: 'background.paper',
            boxShadow: 24,
            width: 500,
            p: 1,
            }}
        >
            <Typography color="primary" variant="h6" component="h2">
                Détails
            </Typography>
            <List>
                <ListItem >
                    <ListItemIcon
                        children={<CalendarTodayIcon/>}
                    />
                    <ListItemText 
                        children={formatDate(date, undefined,{
                            hour: 'numeric',
                            minute: 'numeric'
                        })}
                    />
                </ListItem>
                { 
                    formats .filter((item) => ~fileExtensionBase[item.label].indexOf(getFileExtension(name)))
                    .map((item, index) => (
                        <ListItem key={index}>
                            <ListItemIcon
                            children={item.icon}
                        />
                        <ListItemText 
                        >
                            {item.label}/{getFileExtension(name)}
                        </ListItemText>
                        </ListItem>
                    ))
                }
                <Divider/>

                <ListItem >
                    <ListItemText 
                    >
                        <Box component={PerfectScrollbar} sx={{pb:1}}>
                            <Typography variant='caption'>
                                {getFileName(name)}
                            </Typography>
                        </Box>  
                    </ListItemText>
                </ListItem>
            </List>
                <Button
                    children="ok"
                    variant="contained"
                    size="small"
                    onClick={onClose}
                />
        </Box>
        </Box>
    ) 
}

export default forwardRef(FileDetail);

