import React, { useLayoutEffect } from 'react';
import { ThemeProvider} from '@mui/material';
import {
  ConfigProvider,
  SessionProvider,
  CookieProvider,
  useCookieParam,
  useSessionParam,
  useConfigParam,
} from './services/globalConfig';
import Auth from './routers/Auth';
import useDefautTheme from './config/useDefautTheme';

export default function App() {
    const [config, configActions] = useConfigParam();
    const [session, sessionActions] = useSessionParam();
    const [cookie, cookieActions] = useCookieParam();
    const theme = useDefautTheme(config.themeMode);
    useLayoutEffect(() => {
      document.body.style.backgroundColor = theme.palette.background.default
    },[]);
    return (
      <ThemeProvider {...{theme}}>
        <ConfigProvider value={[config, configActions]}>
          <SessionProvider value={[session, sessionActions]}>
            <CookieProvider value={[cookie, cookieActions]}>
              <Auth/>
            </CookieProvider>
          </SessionProvider>
        </ConfigProvider>
      </ThemeProvider>
    );
}
