import {useState, useRef, Fragment, useContext, useLayoutEffect} from 'react';
import Modal from '@mui/material/Modal';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';
import { Button, IconButton, Snackbar, TextField } from '@mui/material';
import { getFileExtension, getFileName } from '../treatments/getFileExtension';
import fileExtensionBase from '../config/fileExtensionBase';
import CloseIcon from '@mui/icons-material/Close';
import serverPath from '../../../../services/serverPath';
import { CurrentSession } from '../components/Auth';
import axios from 'axios';
import PerfectScrollbar from 'react-perfect-scrollbar';
function FileEditorName(props) {
    const inputTextField = useRef();
    const [currentSession] = useContext(CurrentSession);
  
    const [values, setValues] = useState({
        name: '',
        messageSnak: '',
        alertSnack : false
    })

  
  const handleInputFocus = (event) => {
    event.target.select();
  }
  
  const handleInputBlur = (event)  => {
     if(!event.target.value) {
         setValues({...values, name: getFileName(props.name) || 'text'});
     }
  }
  const handleChangeName = (event) => {
      setValues({...values, name: event.target.value});
  };
  useLayoutEffect(() => {
    if((values.name === '') && props.name) setValues({...values, name: getFileName(props.name)})
  },[props.name])

  const handleEditeFileName = () => {
      const fileExt = getFileExtension(props.name);
      const fileName = (values.name ? values.name.trim() ? 
      values.name.trim() : getFileName(props.name) : 
      getFileName(props.name)) + '.' + fileExt;

      const index = ['doc', 'photo', 'video' ].findIndex((item) => 
      (~fileExtensionBase[item].indexOf(fileExt)));

      const route = serverPath('api/stuff/workspace');
      
      axios({
          method: 'put',
          url: route,
          headers: {
            'Authorization': `Bearer ${currentSession.token}`
          },
          data: {
            oldFilename: props.name,
            filename: values.name,
            path: 'document;images;videos'.split(';')[index],
            userId: currentSession.id
        },
      }).then((result) => {
        if(result.data && (typeof props.onEdite === 'function')) 
            props.onEdite();
      }).catch((error) => {
        console.log(error.toString());
      })
      props.onClose();
  }

 

  return (
    <Fragment>
      <Modal
        disableAutoFocus
        open={Boolean(props.open)}
        onClose={props.onClose}
        aria-labelledby="server-modal-title"
        aria-describedby="server-modal-description"
        sx={{
          display: 'flex',
          p: 1,
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        <Box
          sx={{
            position: 'relative',
            width: 300,
            bgcolor: 'background.paper',
            boxShadow: (theme) => theme.shadows[10],
            p: 1,
          }}
        >
          <Typography  variant="h6"  color="primary">
            Renommer le fichier
          </Typography>
            <Box>
                <TextField
                    inputRef={inputTextField}
                    fullWidth
                    size='small'
                    value={values.name}
                    onFocus={handleInputFocus}
                    onBlur={handleInputBlur}
                    onChange={handleChangeName}
                    autoFocus
                />
                <Box sx={{mt:1}}>
                    <Button 
                    variant="contained"
                    onClick={handleEditeFileName}
                    disabled={
                        (!values.name) || (values.name === (props.name || 'text'))
                    }
                    size="small"
                    >renommez</Button>
                </Box>
            </Box>
        </Box>
      </Modal>

      <Snackbar
        open={Boolean(values.alertSnack)}
        autoHideDuration={2000}
        onClose={() => {
          setValues({...values, alertSnack: false, messageSnak: '' })
      } }
      anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'right'
      }}
      message={values.messageSnak}
      action={
          <IconButton
              size="small"
              color="inherit"
              onClick={() => {
                setValues({...values, alertSnack: false, messageSnak: ''})
              }}
          >
              <CloseIcon/>
          </IconButton>
      }
      />  

    </Fragment>
  );
}

export default FileEditorName;