import React, { useState, useRef, useEffect } from 'react';
import {
  Menu,
  Backdrop,
  CircularProgress,
} from '@mui/material';
import serverPath from '../../../services/serverPath';
import { useSession } from '../../../services/globalConfig';
import TextFieldController from '../../../components/TextFieldController';
import FormInputTheme from '../../../config/FormInputTheme';
import useAxios from 'axios-hooks';
import fileExtensionBase from '../../../config/fileExtensionBase';
import getFileExtension, { getName } from '../../../services/getFileExtension';

export default function RenameFile (props) {
  const { file, anchorEl, noAllowedValues } = props;
  const [{loading}, refecth] = useAxios({url: URL},{manual: true});
  const [,{ getSession }] = useSession();
  const [checking, setChecking] = useState(false);
  const {id: userId, token, } = getSession('user') || {};
  const newName = useRef(null);
  const handleRename = () => {
    const extension = file && getFileExtension(file.name);
    const path = fileExtensionBase
    .find(
      extItem =>
         ~extItem
         .exts
         .indexOf(extension)
    ).type;
    const data = {
      userId,
      path: /document|image|video/.test(path) ? path + 's' : 'documents',
      oldFilename: file.name,
      filename: `${newName.current}`,
    };
    if(newName.current) {
      refecth({
        method: 'put',
        data,
        headers: {
          'Authorization': `Bearer ${token}`
        }
      }).then(() => {
        if(typeof props.onClose) {
          props.onClose({
             fileName: newName.current,
          });
          newName.current = null;
        }
      })
      .catch((error) => {
        if(typeof props.onClose)
          props.onClose({
            type: 'error',
            message: `Le fichier n'a pas pu être renommé`,
            duration: 3000,
            snackbard: true,
            fileName: file.name,
         });
      });
      setChecking(false);
    }
    else {
      setChecking(true);
    }
  }
  useEffect(() => {
    if(!file && checking) setChecking(false);
  }, [file]);

  return (
    <React.Fragment>
      <Backdrop
        open={!!loading}
        sx={{
          color: 'white',
          zIndex: theme => theme.zIndex.drawer,
          backdropFilter: 'blur(15px)',
        }}
      >
        <FormInputTheme mode="dark">
          <CircularProgress
              color="inherit"
              size="small"
              sx={{
                width: 25,
                height: 25,
              }}
          />
        </FormInputTheme>
      </Backdrop>
      <Menu
        open={!!file}
        onClose={() => props.onClose({fileName: (file || {}).name})}
        anchorEl={anchorEl}
        elevation={0}
        PaperProps={{
            sx: {background: 'transparent', p: -1, m:0}
        }}
      >
        <FormInputTheme>
          <TextFieldController
            defaultValue={file && getName(file.name)}
            ref={newName}
            icon={true}
            type="text"
            size="small"
            margin="none"
            sx={{ m: 0, p: 0, backdropFilter: 'blur(15px)', bgcolor: theme => theme.palette.background.paper + '50',}}
            onKeyDown={ event => {
                if(event.keyCode === 13) handleRename();
            }}
            checking={checking}
            helperTextError={`Ce fichier existe déjà`}
          />
        </FormInputTheme>
      </Menu>
    </React.Fragment>
    
  );
}

const URL = serverPath('/api/stuff/workspace');
