import { useEffect, useRef, useState } from 'react';
import {
    Box,
    Card,
    CardActions,
    CardContent,
    CardHeader,
    Typography,
    useTheme,
    // Button,
    // TextField,
    // Checkbox,
    // FormControl,
    // FormControlLabel,
    Avatar,
    Divider,
    Snackbar,
    Alert,
    //IconButton
} from '@mui/material';
import LockRoundedIcon from '@mui/icons-material/LockRounded';
import { Link, useNavigate } from 'react-router-dom';
import FormInputTheme from '../config/FormInputTheme';
// import AdminPanelSettingsRoundedIcon from '@mui/icons-material/AdminPanelSettingsRounded';
// import CloseIcon from '@mui/icons-material/Close';
import useAxios from 'axios-hooks'
import serverPath from '../services/serverPath';
import LoadingButton from '@mui/lab/LoadingButton';
import SupervisorAccountRoundedIcon from '@mui/icons-material/SupervisorAccountRounded';
import TextFieldController from '../components/TextFieldController';
import refStructObj from '../services/refStructObj';
import { useSession } from '../services/globalConfig';
import config from '../config/app.json';

export default function AdmiLogin (props) {
    const [server, refetch, cancelRequest] = useAxios(URI, {manual: true});
    const [,{setSession}] = useSession();
    const [values, setValues] = useState({
        chicking: false,
        snackOpen: false
    });
    const theme = useTheme();
    const email = useRef(null);
    const password = useRef(null);
    const navigateTo = useNavigate();
    const color = theme.palette.mode === 'dark' ? 'inherit' : 'primary';
    const handleSendForm = event => {
        event.preventDefault();
        if(!email.current) setValues({...values, chicking: 'email'});
        else if (!password.current) setValues({...values, chicking: 'password'});
       else
       refetch({
            method: 'post',
            data: {email: email.current, password: password.current},
        });
    };
    const handleCloseSnack =  () => setValues({...values, snackOpen: false});
    useEffect(() => {
        if(server.data) {
             if(~server.data.userGrade.permission.indexOf('admin'))
                setSession('admin', 
                    refStructObj(
                        server.data, 
                        config.server.refkeys,
                    )
                );
        }
        if(server.error)
            setValues({...values, snackOpen: true});
        return server.loading ? cancelRequest : (() => {});
    },[server.data, server.error]);
    return (
        <Box
            sx={{
                minHeight: 412,
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                flex: 1
            }}
        >
            <Box
                component={Card}
                elevation={0}
                sx={{
                    minWidth: 350,
                    minHeight: 200,
                    mt: 5,
                    mb: -5,
                    border: theme => `1px solid ${theme.palette.divider}`
                }}
            >
                <CardHeader
                    title={
                        <Typography variant="h5"
                            color={color}
                        >
                            Administrateur GEID
                        </Typography>
                    }
                />
                <FormInputTheme>
                    <CardContent>
                        <Divider textAlign="left">
                            <Avatar>
                                <SupervisorAccountRoundedIcon />
                            </Avatar>
                        </Divider>
                        <Box>
                            <Box component="form" onSubmit={handleSendForm} >
                                <TextFieldController
                                    label="Adresse Electronique"
                                    size="small"
                                    margin="dense"
                                    fullWidth
                                    ref={email}
                                    type="email"
                                    checking={values.checking === 'email'}
                                    //color={color}
                                />
                            </Box>
                            <Box>
                                <TextFieldController
                                    label="Mot de Passe"
                                    size="small"
                                    margin="dense"
                                    fullWidth
                                    ref={password}
                                    checking={values.checking === 'password'}
                                    //color={color}
                                />
                            </Box>
                        </Box>
                    </CardContent>
                </FormInputTheme>
                <CardActions>
                    <LoadingButton
                        sx={{mx:1}}
                        startIcon={<LockRoundedIcon/>}
                        size="small" variant="outlined"
                        type="submit"
                        LinkComponent="input"
                        loading={server.loading}
                        onClick={handleSendForm}
                        color={color}>connexion</LoadingButton>
                </CardActions>
            </Box>
            <Snackbar
                anchorOrigin={{
                    vertical: 'bottom',
                    horizontal: 'center'
                }}
                onClose={handleCloseSnack}
                open={values.snackOpen}
                message={server.error && server.error.message.toString()}
                autoHideDuration={5000}
            >
                <Alert
                     severity="error"
                     children={server.error && server.error.message.toString()}
                />
            </Snackbar>
        </Box>
    )
}

const URI = serverPath('api/auth/login');
