import React, {
    useRef,
    forwardRef,
    useEffect,
} from 'react';
import {
    BrowserRouter,
    Routes as Switch,
    Route,
    Navigate,
    useLocation,
} from 'react-router-dom';
import routes, { routeDisp } from './routes';
import { Box } from '@mui/material';
import Footer from '../components/Footer';
import HeaderLink from '../components/HeaderTitle';
import NotFound from '../views/NotFoud';
import SettingsNav from '../components/SettingsNav';
import { useSession } from '../services/globalConfig';
import Admi from '../private/Admi';
import AdmiLogin from '../private/AdmiLogin';
import ScrollTopFab from '../components/ScrollTopFab';
 
export default function Auth () {
    const [,{getSession}] = useSession();
    const isAuth = getSession('user');
    const fabEl = useRef();

    return (
        <Box sx={{
                bgcolor: 'background.default',
                minHeight: '100vh',
                color: 'text.primary'
            }}
        >
            <SettingsNav/>
                <React.Fragment>
                    <HeaderLink/>
                    <BrowserRouter>
                        <WrapperSCrollTop
                            onChange={(oldL, newL) => {
                                    if(oldL.current.pathname !== newL.pathname) {
                                        oldL.current = newL;
                                        fabEl.current.click();
                                    }
                            }}
                            ref={fabEl}
                        >
                            <Switch>
                            {routes.map((route, index) => {
                                const accessMode = isAuth ? 'private' : 'public';
                                return RegExp(route.accessMode).test(accessMode) && (
                                    <React.Fragment key={index}>{routeDisp(route)}</React.Fragment>
                                );
                            })}
                                <Route
                                    path='/administrator'
                                    element={!!getSession('admin') ?
                                    <Admi/> : <AdmiLogin/>}
                                />
                                <Route path='*' element={<NotFound/>}/>
                                <Route exact path='/' element={<Navigate to="/home"/>}/>
                            </Switch>
                        </WrapperSCrollTop>
                    </BrowserRouter>
                </React.Fragment>
            <Footer/>
        </Box>
    )
}

const WrapperSCrollTop = forwardRef((props, ref) => {
    const { children, onChange } = props;
    const currentLocation = useLocation();
    const oldLocation = useRef(currentLocation);

    useEffect(() => {
        if(typeof onChange === 'function')
            onChange(oldLocation, currentLocation);
    });
    return (
        <React.Fragment>
            {children}
            <ScrollTopFab
                ref={ref}
            />
        </React.Fragment>
    );
});
