import { Drawer, ListItemIcon, ListItemText, MenuItem, MenuList, Popover, Typography, } from '@mui/material'
import Menu from '@mui/material/Menu'
import { Fragment, useState } from 'react';
import ChevronRightIcon from '@mui/icons-material/ChevronRight';

function FileNav(props) {
        const { options, anchorEl } = props

    return (
        <Fragment>
            <Menu 
                anchorEl={anchorEl} 
                keepMounted 
                open={Boolean(anchorEl)} 
                onClose={props.onClose}
            >
                    {
                        options.map((option, index) => (
                                <MenuItem 
                                    children={option.label}
                                    key={index}
                                    onClick={ () => {
                                        if(option.action) option.action();
                                        if(props.onClose && option.close) props.onClose();
                                    }}
                                >
                                    <ListItemIcon  >
                                        {option.icon}
                                    </ListItemIcon>
                                    <ListItemText sx={{flexGrow: 1}}>{option.label}</ListItemText>
                                </MenuItem>
                        ))
                    }
        </Menu>
        
       </Fragment>)
}

export default FileNav;