import * as React from 'react';
import TabsUnstyled from '@mui/base/TabsUnstyled';
import TabsListUnstyled from '@mui/base/TabsListUnstyled';
import TabPanelUnstyled from '@mui/base/TabPanelUnstyled';
import { buttonUnstyledClasses } from '@mui/base/ButtonUnstyled';
import TabUnstyled, { tabUnstyledClasses } from '@mui/base/TabUnstyled';
import { styled } from '@mui/system';
import { Divider, useTheme, Typography } from '@mui/material';



const TabsList = styled(TabsListUnstyled)`
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    align-content: space-between;
`;

function AppTabList(props) {

    const {data} = props;
    const theme = useTheme();
    const Tab = styled(TabUnstyled)`
    fontFamily: "\"Roboto\", \"Helvetica\", \"Arial\", sans-serif";
    fontSize: "1.25rem";
    fontWeight: 500;
    letterSpacing: "0.0075em";
    lineHeight: 1.6;
    cursor: pointer;
    background-color: transparent;
    width: 100%;
    border: none;
    display: flex;
    justify-content: center;
    color: ${theme.palette.action.disabled};

    &:hover {
        
    }

    &:focus {
        border-radius: 3px;
        outline-offset: 2px;
    }

    &.${tabUnstyledClasses.selected} {
        color: ${theme.palette.text.primary};
    }

    &.${buttonUnstyledClasses.disabled} {
        opacity: 0.5;
        color :red;
        cursor: not-allowed;
    }
    `;

  return (
    <TabsUnstyled defaultValue={0} value={props.value} onChange={props.onChange}>
        <Divider
            textAlign="left"
        >
            <TabsList
            >
                {data.map((tab, index) => (
                    <Tab sx={{fontSize: '1.25rem'}} key={index}>
                      {tab.label}
                    </Tab>
                ))}
            </TabsList>   
        </Divider>
        {data.map((tab, index) => (
            <TabPanelUnstyled value={index} key={index}>
                {tab.content}
            </TabPanelUnstyled>
        ))}
    </TabsUnstyled>
  );
}
export default AppTabList;