import { AppBar, IconButton, Toolbar, Typography, useMediaQuery } from "@mui/material";
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import { useData } from "../treatments/globalData";
import capStr from '../treatments/capStr';

function AppHeader({children, title, icon, handleBoxContent, ...otherProps}) {
    const { screen } = useData();
    const isMiddleScreen = true;// useMediaQuery(screen);
    const handleBackClick = () => {
        handleBoxContent(false);
    };

    return (
        <AppBar {...otherProps}
            sx={{
                position: 'sticky', 
                top: 0, 
                backdropFilter: 'blur(15px)',
                bgcolor: theme => theme.palette.background.paper + '50'
            }}
        >
                    <Toolbar>
                        <IconButton 
                            onClick={handleBackClick}
                            sx={{mr:1}}
                        >
                            <ArrowBackIosNewIcon/>
                        </IconButton>
                        <Typography 
                            sx={isMiddleScreen ? {} : {flexGrow: 1}}
                            color="primary" 
                            variant="h6"
                        >
                            {icon} {capStr(title)}
                        </Typography>
                        {children}
                    </Toolbar>
        </AppBar>
    )
}

AppHeader.defaultProps = {
    position: 'sticky',
    color: 'default'
}

export default AppHeader;