import {
    AppBar,
    Toolbar,
    IconButton,
    Typography,
    useTheme,
} from '@mui/material';
import Menu from '@mui/icons-material/Menu';
import { useContext } from 'react';
import { TextEditorProps } from '../TextEditor';
import MenuOpenRoundedIcon from '@mui/icons-material/MenuOpenRounded';

export default function TextEditorHeader (props) {
    const [context, handleChange] = useContext(TextEditorProps);
    const theme = useTheme();
    const color = theme.palette.mode === 'dark' ? 'inherit' : 'primary';
    return (
        <AppBar 
            position="sticky" 
            sx={{
                bgcolor: theme => theme.palette.background.paper + 'ee',
                backdropFilter: 'blur(15px)',
            }}
        >
          <Toolbar>
            <IconButton edge="start" color="inherit" aria-label="menu">
            {!context.openNavLeft &&
            <IconButton
                size="small"
                edge="start"
                onClick={handleChange('openNavLeft', !context.openNavLeft)}
            >
                <MenuOpenRoundedIcon />
            </IconButton>}
            </IconButton>
            <Typography variant="h6" color={color} sx={{mx:1, flexGrow: 1}}>
                Editeur de documents
            </Typography>
          </Toolbar>
        </AppBar>
    );
}