import React from 'react';
import Paper from '../../../components/Paper';
import getFileExtension from '../../../services/getFileExtension';
import VideoPlan from '../../../components/VideoPlan';
import ImagePlan from '../../../components/ImagePlan';
import useSize from '../../../services/useSize';

import {
    Box,
    Grid,
    ImageList,
} from '@mui/material';
import ElementItem from './ElementItem';

export default function WorkspacesContent (props) {
    const { tab, data, openNavLeft  } = props;
    const size = useSize();
    return (
      <Box sx={{height: '95vh', overflow: 'auto', width: '100%',}}>
          {/documents/.test(tab) &&
          <Box component={Grid} container>
              {
                  data[tab].map((doc, index, docs) => (
                      <Box 
                        sx={{px:1}} 
                        component={Grid} 
                        item key={index} 
                        xs={size.value({
                            xs: 6,
                            md: openNavLeft ?  1.5 : 1.2,
                            lg: openNavLeft ?  1.5 : 1.2,
                            xl: openNavLeft ?  1.2 : .9,
                        })}
                        >
                        <ElementItem
                            file={doc}
                            files={docs}
                        >
                            <Paper
                              label={doc.name}
                              ext={getFileExtension(doc.name)}
                              link={doc.url}
                            />
                        </ElementItem>
                      </Box>
                  ))
              }
          </Box>
          }
          {/others/.test(tab) &&
            <Box component={Grid} container>
                {
                    data[tab].map((doc, index, docs) => (
                        <Box 
                            sx={{px:1}} 
                            component={Grid} 
                            item 
                            key={index} 
                            xs={size.value({
                                xs: 6,
                                md: openNavLeft ?  1.5 : 1.2,
                                lg: openNavLeft ?  1.5 : 1.2,
                                xl: openNavLeft ?  1.2 : .9,
                            })}
                        >
                            <ElementItem
                                file={doc}
                                files={docs}
                            >
                                <Paper
                                label={doc.name}
                                ext={getFileExtension(doc.name)}
                                link={doc.url}
                                />
                            </ElementItem>
                        </Box>
                    ))
                }
            </Box>
          }
          {/images/.test(tab) &&
            <ImageList 
                cols={size.value({
                    xs: 2,
                    md: openNavLeft ?  4 : 6,
                    lg: openNavLeft ?  4 : 6,
                    xl: openNavLeft ?  6 : 9,
                })}
                sx={{overflow: 'auto', m: 1,}}
            >
                {data[tab]
                    .map((image, index, images) => (
                        <ElementItem
                            file={image}
                            files={images}
                            key={index}
                        >
                            <ImagePlan
                                label={image.name}
                                src={image.url}
                            />
                        </ElementItem>
                    ))
                }
            </ImageList>
          }
          {/videos/.test(tab) &&
          <Box component={Grid} container>
              {
                  data[tab].map((video, index, videos) => (
                      <Box 
                        sx={{px:1}} 
                        component={Grid} 
                        item 
                        key={index} 
                        xs={size.value({
                            xs: 2,
                            md: openNavLeft ?  3 : 12/5,
                            lg: openNavLeft ?  3 : 12/5,
                            xl: openNavLeft ?  12/5 : 12/7,
                        })}
                      >
                          <ElementItem
                            file={video}
                            files={videos}
                          >
                            <VideoPlan
                                label={video.name}
                                src={video.url}
                            />
                          </ElementItem>
                      </Box>
                  ))
              }
          </Box>
          }
      </Box>
    )
}
