import { keyWord, encrypt, decrypt } from "./crypt";

export const parse = (data) => {
    try {
        return data ? (typeof data === 'string') ? JSON.parse(data) : JSON.stringify(data) : null;
    } catch (error) {
        return null;
    }
}

export const get = (type) => {
    const localStorageData = parse(decrypt(window.localStorage.getItem(keyWord)));
    const sessionStorageData = parse(decrypt(window.sessionStorage.getItem(keyWord)));
   
    const defaultValue = {
        theme: 'light',
        lang: 'fr-FR',
        cookie: null,
        settingsOpen: null
    };
    const init = {
        local: {
            ...defaultValue,
            ...(localStorageData || {}),
        },
        session: sessionStorageData ? sessionStorageData : null
    }
    return type === 'session' ? sessionStorageData : ( type === 'local' ? localStorageData : init );  
}

export const set = (type, data) => {
    switch(type) {
        case 'session':
            window.sessionStorage.setItem(keyWord, encrypt(parse(data)));
            break;
        case 'local':
            window.localStorage.setItem(keyWord, encrypt(parse(data)));
            break;
        default:
            if(type === 'object') {
                Object.keys(type).forEach((subType) => {
                    if(window[subType + 'Storage'])
                    window[subType + 'Storage'].setItem(keyWord, encrypt(parse(type[subType])));
                });
            }
    }
}

export const del = (type) => {
    switch(type) {
        case 'session':
            window.sessionStorage.clear(keyWord);
            break;
        case 'local':
            window.localStorage.clear(keyWord);
            break;
        default:
            window.sessionStorage.clear(keyWord);
            window.localStorage.clear(keyWord);
    }
}