function TreeStructure(props) {
    const { open, width, onClose  } = props;
    const [,{getSession}] = useSession();
    const currentSession = getSession('user');
    const [values, actions] = useContext(archiveContext);

    const [treeData, setTreeData] = useState({
        name: currentSession.level.role,
        children: null,
        index: 0,
        saveStructure: [],
    });

    const handleGetData = (data, ref, role) => {
        const params = localStorageData.parse({
          userId:  currentSession.id,
		      structName: role
        });
        const route = serverPath(`api/stuff/archives/struct/${params}`);


        axios.get(route, 
            { headers: 
                {'Authorization' : `Bearer ${currentSession.token}`} 
        }).then((result) => {

        const cloneData = {...data};
        const pathsData = ref.split('#####');
        let refData = null;
        pathsData.forEach((path) => {
            if(Boolean(path)) {
                if(refData === null) refData = cloneData[path];
                else refData = refData[path];
            }
        })

        actions.handleChangeProps({
          docTypes: result.data.docTypes, 
          role:role, 
          loading: (values.role !== role)
        });

        if(!~cloneData.saveStructure.indexOf(role + ref)) {
            if(refData) {
                refData.children = {};
                result.data.childs.forEach(
                        (name) => {
                            refData.children[name] = {
                                index: cloneData.index + 1,
                                children: null
                            }
                        });
            } else {
                cloneData.children = {};
                result.data.childs.forEach(
                    (name) => {
                        cloneData.children[name] = {
                            index: cloneData.index + 1,
                            children: null
                        }
                    });
            }
        }
            setTreeData({...cloneData, saveStructure: [role + ref,...cloneData.saveStructure]});
        }).catch((error) => {
            console.log(error.toString());
        });

    }
    const handleChildren = (event, node) => {
        const [ label, index, ref ] = node.split('_____');
        handleGetData(treeData, ref, label.trim());
    };

    return(
        <Box>
             <Drawer
                open={open}
                anchor="left"
                variant="persistent"
                sx={{
                    zIndex: 0,
                    '& .MuiDrawer-paper': { 
                        top:120, 
                        boxSizing: 'border-box',
                        width: width
                    },
                }}
                >
                    <Box sx={{textAlign:'right', p:1}}>
                        <IconButton
                            onClick={onClose}
                        >
                            <ChevronLeftIcon/>
                        </IconButton>
                    </Box>
                    <Divider/> 
                    <PerfectScrollbar
                        style={{height: '70vh', padding: 5}}
                    >
                    
                      <TreeView
                          aria-label="file system navigator"
                          defaultCollapseIcon={<MinusSquare />}
                          defaultExpandIcon={<PlusSquare />}
                          defaultEndIcon={<CloseSquare />}
                          
                          sx={{ 
                              flexGrow: 1,
                              overflow: 'hidden',
                              minHeight: '70vh',
                              mt:1
                          }}
                          onNodeFocus={handleChildren}
                      >
                          <Tree 
                              name={treeData.name}
                              children={treeData.children}
                              index={treeData.index}
                              refPath=""
                          />
                      </TreeView>
                
                    </PerfectScrollbar>
             </Drawer>
        </Box>
    )
}

function Tree(props) {
    const { name, children, index, refPath } = props;

    return(
        <Fragment>
            <StyledTreeItem nodeId={`${name}_____${index}_____${refPath}`} label={name}>
                {children && Object.keys(children).map((treeData, indexTree) => (
                    <Tree
                        name={treeData}
                        children={children[treeData].children}
                        refPath={`${refPath}#####children#####${treeData}`}
                        index={index+1}
                        key={indexTree}
                    />
                ))}
                {(children === null) ?
                 (<Fragment>
                     <CircularProgress sx={{top:2, position: 'relative', mr:1}} 
                        size={15} 
                    />
                    <Typography variant='caption'>chargement...</Typography>
                </Fragment>) :
                (Object.keys(children).length === 0 &&
                <Typography 
                    align="center" 
                    paragraph 
                    variant="caption" 
                    color="text.secondary"
                >aucun élement</Typography>)
                }
            </StyledTreeItem>
        </Fragment>
    );
}

export default TreeStructure;