export const mediaLibrary = createContext(null);

const MediaLibraryProvider = mediaLibrary.Provider;

const useMediaLibraryData = (init) => {
    const [values, setValues] = useState({
        role: init.role,
        loading: true,
        docTypes: init.docTypes,
        data: {
            library: null,
            films: null,
            pictures: null
        },
    });

    const actions = {
        handleChangeProps(props, value) {
            setValues({...values, ...(typeof props === 'string' ? {props : value} : props)})
        }
    };
    return [values, actions];
};

const icons = [ LocalLibraryIcon, MovieFilterIcon, BurstModeIcon ]

