import { Box, 
    Card, 
    CardContent, 
    Grid, 
    Skeleton, 
    useTheme, 
    CardHeader, 
    Typography, 
    CardActions, 
    Button, 
    Stack
} from "@mui/material";
import { BookCover } from 'book-cover-3d';
import { ColorExtractor } from 'react-color-extractor'
import { useState} from 'react';
import CropText from './CropText';

export default function BookPlan(props) {
    const { title, date, link } = props;
    const [colors, setColors] = useState([]);
    const theme = useTheme();
    const handleGetColors = colors => setColors([...colors]);
    return (
        <Card elevation={0} 
            sx={{
                borderRaduis: 5,
                border: theme => `1px solid ${theme.palette.divider}`
            }}
        >
            <CardContent>
                <Stack direction="row">
                    <Box>
                        <BookCover 
                            width={100} 
                            height={130} 
                            thickness={18} 
                            radius={2} 
                            rotate={45}
                            bgColor={colors[0] || theme.palette.divider}
                            shadowColor={theme.palette.divider}
                        >
                            <ColorExtractor
                                getColors={handleGetColors}
                                children={
                                    <img
                                        component="img"
                                        src={props.coverUrl || URI_IMAGE}
                                        hidden={!colors.length}
                                    />
                                }
                            />
                            {
                                !colors.length &&
                                <Skeleton
                                    width={100}
                                    height={130}
                                    variant="rectangular"
                                    animation="wave"
                                />
                            }
                        </BookCover>
                    </Box>
                    <Box>     
                        <Box>
                            <CardHeader
                                title={
                                    <Typography component="div">
                                        {title.length > 20 ? 
                                            (<CropText
                                                len={16}
                                            >{title}</CropText>)
                                            : title}
                                    </Typography>
                                }
                                subheader={
                                    <Typography component="div" variant="caption">
                                        {date}
                                    </Typography>
                                }
                            />
                            <CardActions>
                                <Button 
                                    variant="outlined"
                                    size="small"
                                    LinkComponent="a"
                                    target="_blank"
                                    href={link}
                                    color={theme.palette.mode === 'dark' ? "inherit" : "primary"}
                                >lire le document</Button>
                            </CardActions>
                        </Box>
                    </Box>
                </Stack>
            </CardContent>
        </Card>
    )    
}
const URI_IMAGE = require('../assets/book_cover.png');
BookPlan.defaultProps = {
    title: 'Titre de mon document',
    date: 'mer 01.01.2022' 
};