import React from 'react';
import {
    Drawer,
    Card,
    Box,
    CardHeader,
    CardContent,
    IconButton,
    List,
    Typography,

} from '@mui/material';
import KeyboardArrowDownRoundedIcon from '@mui/icons-material/KeyboardArrowDownRounded';
import { useSession } from '../../../services/globalConfig';
import fileExtensionBase from '../../../config/fileExtensionBase';
import getFileExtension, { getName } from '../../../services/getFileExtension';
import serverPath from '../../../services/serverPath';
import UploadProgressStatus from '../components/UploadProgressStatus';

const UploadNav = React.forwardRef((props, ref) => {
     const [open, setOpen] = React.useState(null);
     const filesUploads = React.useRef([]);
     const uploadsCurrentNbr = React.useRef(0);
     const [,{getSession}] = useSession();
     const div = React.useRef();

     const handleSendData = file => {
        const {id:userId, token, } = getSession('user');
        const { type } = fileExtensionBase.find(
            item => ~item.exts
            .indexOf(getFileExtension(file.name))) || 'document' ;
        const infos = {
            userId,
            filename: getName(file.name),
            path: type ? type === 'audio' ? 'documents' : type + 's' : 'documents',
            file,
        };

        const data = new FormData();
        Object.keys(infos).forEach(key => {
            data.append(key, infos[key]);
        });

        const xhr = new XMLHttpRequest();
        xhr.open('post', WORKSPACE_URL);
        xhr.setRequestHeader('Authorization', `Bearer ${token}`);
        xhr.addEventListener('loadstart', () => {
            uploadsCurrentNbr.current += 1;
            setOpen(Math.random().toString());
        });
        xhr.upload.addEventListener('progress', event => {
            const {loaded, total} = event;
            const endTime = new Date().getTime();
            const duration = (endTime - startTime) / 1000;
            const bbs = loaded / duration
            upl.total = total;
            upl.loaded = loaded;
            upl.timeout = (loaded - total) / bbs;
        });
        xhr.addEventListener('load', event => {
        //if(xhr.readyState === 4 ) {
                upl.total = file.size;
                upl.loaded = file.size;
                upl.state = 'end';
                upl.timeout = 0;
                uploadsCurrentNbr.current -= 1;
                setOpen(open ? Math.random().toString() : open === false ? null : false);
         //   };
        });
        xhr.addEventListener('error', () => {
            uploadsCurrentNbr.current -= 1;
        });
        xhr.addEventListener('abort', () => {
            uploadsCurrentNbr.current -= 1;
        });
        const startTime = new Date().getTime();
        const id = filesUploads.current.length;
        const upl = {
            id,
            total: file.size,
            loaded: 0,
            name: file.name,
            state: 'start',
            target: xhr,
            size: file.size,
            timeout: null,
            startTime,
            cancel () {
                if(xhr.readyState < 4) xhr.abort();
                delete filesUploads.current[id];
                setOpen(Math.random().toString());
            },
        };
        filesUploads.current.push(upl);
        xhr.send(data);
    };

    React.useEffect(() => {
        if(ref) ref.current.el = div.current;
        if(typeof props.onUploads === 'function' && filesUploads.length) {
            props.onUploads({
              nbr: filesUploads.current.filter(e => e).length,
              current: uploadsCurrentNbr.current,
            });
        }
    });

    return (
        <React.Fragment>
             <div ref={div}
                onClick={() => {
                    const { file } = ref.current || {};
                    if(file) {
                         handleSendData(file);
                         ref.current.file = null;
                    }
                    setOpen(file || !open);
                }}
             />
             <Drawer
                variant="persistent"
                anchor="bottom"
                open={!!open}
                PaperProps={{
                    sx: {
                    borderRadius: 1,  
                    border: 'none', 
                    right: 0,
                    left: window.innerWidth -400,
                    bgcolor: 'transparent',
                }}}
             >
                <Box
                component={Card}
                sx={{
                    height: 300,
                    backdropFilter: 'blur(15px)',
                    bgcolor: theme => theme.palette.background.paper + 'ee',
                    border: theme => '1px solid '+ theme.palette.divider,
                }}
                >
                    <CardHeader
                    action={
                        <IconButton
                            size="small"
                            onClick={() => setOpen(null)}
                        >
                        <KeyboardArrowDownRoundedIcon/>
                        </IconButton>
                    }
                    title="Téléchargement"
                    titleTypographyProps={{
                        fontSize: 18,
                        variant: 'h6'
                    }}
                    />
                    <CardContent>
                    {filesUploads.current.filter(e => e).length ?
                        <List
                        sx={{
                            height: 180,
                            overflow: 'auto'
                        }}
                        >
                        {
                            [...filesUploads.current.map((upload, index) => (
                                <UploadProgressStatus
                                    key={index}
                                    uploadInfos={upload}
                                />
                            ))].reverse()
                        }
                        </List> :
                    <Typography
                        align="center"
                        paragraph
                        variant="body2"
                        color="text.secondary"
                        sx={{mt:8}}
                    >
                        Aucun téléchragement en cours
                    </Typography>
                    }
                    </CardContent>
                </Box>
             </Drawer>
        </React.Fragment>
    )
})

const WORKSPACE_URL = serverPath('/api/stuff/workspace');
export default UploadNav;
