import { 
    Box, 
    Grid, 
    Pagination, 
    Stack, 
    Typography, 
    CardMedia, 
    Link, 
    useTheme, 
    IconButton, 
    ImageList, 
    ImageListItem, 
    ImageListItemBar, 
    Tooltip,
    useMediaQuery
} from "@mui/material";
import { useState } from 'react';
import CloseIcon from "@mui/icons-material/Close";
import InfoIcon from "@mui/icons-material/Info";
import { useData } from "../treatments/globalData";
import formatDate from "../treatments/formatDate";
import MoreVertIcon from '@mui/icons-material/MoreVert';

function AppViewerPicture(props) {
    const { fullScreen, onOpen } = props;
    const { local, screen } = useData();
    const theme = useTheme();
    const isMiddleScreen = true // useMediaQuery(screen);
    const [values, setValues] = useState({
        row: 12,
        min: 0,
        dataNbr: props.data.length,
        open: false,
    })
    
    const handleFullScreen = (event) => {
        event.preventDefault();
        if(typeof onOpen === 'function') onOpen(fullScreen ? null : 'photo');
        setValues({...values, row: values.row === 12 ? 48 : 12 });
    };

    const handleOpenFile = (link) => (event) => {
        event.preventDefault();
        const linkComponent = document.createElement('a');
        linkComponent.href = link;
        linkComponent.target= '_blank';
        document.body.appendChild(linkComponent);
        linkComponent.onclick = (event) => {
            document.body.removeChild(event.target);
        }
        linkComponent.click();
    };

    return(
        <Box  container component={Grid} spacing={0}>
            <Box  xs={12} item component={Grid}>
            { props.data.length === 0 &&
            (<Box item component={Grid} xs={12}>
                <Typography color="text.secondary" paragraph align="center" variant="h5">
                    Aucune photo trouvée
                </Typography>
            </Box>)
            }
                <ImageList  cols={isMiddleScreen ? 6 : 2}>
                    {props.data.slice(values.min, values.row).map((archive, index) => (
                        <ImageListItem  
                            key={index}
                            loading="lazy"
                        >
                            
                            <img
                                src={archive.contentUrl || archive.url || archive.fileUrl}
                                //srcSet={archive.contentUrl}
                                alt={archive._id}
                                style={{
                                    cursor: "pointer"
                                }}
                                onClick={handleOpenFile(archive.contentUrl || archive.url)}
                                
                            />
                            <ImageListItemBar
                                title={archive.designation || archive.title || archive.name}
                                subtitle={ formatDate(archive.createdAt, 'fr-FR')}
                                //position="below"
                                actionIcon={
                                <IconButton
                                  onClick={props.actionsDetail ? props.actionsDetail(archive) : null}
                                  sx={{
                                    "& > *": {
                                        color: 'white'
                                    }
                                }}
                                >
                                    <Tooltip arrow title="Detail">
                                        <MoreVertIcon/>
                                    </Tooltip>
                                </IconButton>
                                }
                            />

                        </ImageListItem>
                    ))}
                </ImageList>
                </Box>
            {(values.fullScreen && (parseInt(values.dataNbr/ 32) > 1))
            && (
            <Box sx={{display: 'flex', flexDirection: 'row', flex: 1}}>
                <Stack  direction="row" sx={{ flex: 1, mt: 2}}  spacing={2}>
                    <Pagination sx={{m:'auto'}} count={parseInt(values.dataNbr/ 32)} color="primary" />
                </Stack>
            </Box>)
            }
            { (!fullScreen && (values.dataNbr > 8)) &&
                <Box item xs={12} component={Grid}>
                    <Box sx={{p:1, flex: 1, textAlign: 'right'}} direction="row-inverse">
                        <Link onClick={handleFullScreen} href="#">voir plus des photos</Link>
                    </Box>
                </Box>
            }
        </Box>
    );
}

export default AppViewerPicture;