import { createTheme } from '@mui/material';
import useSystemTheme from '../services/useSytemTheme';
import config from './app.json';

export default (themeMode => {
    const systemMode = useSystemTheme();
    const mode = themeMode === 'system' ? systemMode : themeMode;
    return createTheme({
        palette: {
            mode,
            primary: {
                main: config.theme.primaryColor
            },
            background: {
                default: mode === 'dark' ? '#00173e' : '#eeeeee',
                paper: mode === 'dark' ? '#09162a' : '#ffffff'
            }
        }
})})
