import React, { useState, useRef } from 'react';
import {
    Snackbar,
    Alert,
    IconButton,
    Button,
    Fade,
    Box,
} from '@mui/material';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import options from '../options/options';
import useDelete from '../options/delete';
import About from '../../../components/About';
import RenameFile from './RenameFile';
import SendNav from './SendNav';

export default function ElementItems (props) {
   const {file, files, ...otherProps} = props;
   const [handleDelete, deleteLoading, cancel] = useDelete(file);
   const [values, setValues] = useState({
     ...init,
     fileName: file.name,
   });
   const anchorEl = useRef(null);
    const handleClose = () => setValues({
      ...init,
      fileName: file.name
    });
    const actions = [
        handleDelete(
          () => setValues({...values, snackbard: true }),
          (error) => {
            if(error) setValues({
                ...values,
                type: 'error',
                snackbard: true,
                duration: 3000,
                message: `
                Le fichier n'a pas pu etre supprimé`,
            })
            else setValues({
              ...init,
              fileName: file.name,
              closeEl: true,
          });
        }),
        () => setValues({
          ...values,
         fileRenamed: file,
        }),
        () => setValues({
          ...values,
          sendNav: true
        }),
        () => setValues({
          ...init,
          fileName: file.name,
          about : !values.about
        }),
    ];
    const children = React.Children.toArray(props.children)
    .map((child, index) => React.cloneElement(child,
            {...otherProps,
                label: values.fileName,
                options: options.map((option, index) => ({
                    ...option,
                    action: actions[index],
                }))
            }
        )
    );
    const open = !!(values.snackbard || !!deleteLoading);
    return ( !values.closeEl &&
        <React.Fragment>
            <Fade in={values.type === 'error' ? true : !values.snackbard}>
              <Box
                sx={{
                  zIndex: (theme) =>
                  values.fileRenamed ? theme.zIndex.drawer + 50 : 1,
                }}
                ref={anchorEl}
                children={children}
               />
            </Fade>
            <RenameFile
              onClose={data => setValues({
                ...init,
                ...data,
              })}
              file={values.fileRenamed}
              anchorEl={anchorEl.current}
              noAllowedValues={files.map(file => file.name).join('|')}
            />
            <About
              open={values.about}
              onClose={() => setValues({...values, about: false})}
              file={{
                name: file.name,
                size: 15237,
                lastModifiedDate: new Date(),
              }}
            />
            <Snackbar
                onClose={values.duration && handleClose}
                open={open}
                message={values.message}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
                autoHideDuration={values.duration}
                {...values.type === 'normal' ?
                    {
                        message: (values.message || 'suppression en cours ...'),
                        action: (
                            <Button
                                size="small"
                                onClick={() => {
                                  cancel();
                                  handleClose();
                                }}
                                color="inherit"
                            > annuler </Button>
                        ),
                    } :
                    {
                        children: (
                            <Alert
                                severity={values.type}
                                children={values.message}
                                action={
                                  <IconButton
                                    size="small"
                                    onClick={handleClose}
                                    children={<CloseRoundedIcon/>}
                                  />
                                }
                            />
                        )
                    }
                }
            />
            <SendNav
              open={values.sendNav}
              file={file}
              onClose={() => setValues({...values, sendNav: false})}
            />
        </React.Fragment>
    );
}

ElementItems.defaultProps = {
  files: [],
  file: {},
};

const init = {
   fileRenamed: null,
   sendNav: false,
   about: false,
   snackbard: false,
   type: 'normal',
   message: null,
   closeEl: false,
   duration: null,
};
