import { Typography, Button, Box, Card, Tooltip, IconButton} from '@mui/material';
import { useData } from '../treatments/globalData';
//import InfoIcon from "@mui/icons-material/Info";
import MoreVertIcon from '@mui/icons-material/MoreVert';
import { useState } from 'react';
const text = require('../config/lang_fr');

function Book(props) {
    const {cover, title:bookTitle, link, time} = props
    const [values, setValues] = useState({
        actionButton: null
    });
    const title = bookTitle && bookTitle.replace(/_/g, ' ')
    const handleChangeProps = (prop, value) => {
        setValues({
            ...values,
            ...(typeof prop === 'string' ? {[prop]: value} : prop)
        })
    }
    const handleMouseEnter = () => {
        handleChangeProps({
            actionButton: true,
        })
    }

    const handleMouseLeave = () => {
        handleChangeProps({
            actionButton: false,
        })
    }

    return(
        <Box onMouseEnter={handleMouseEnter} onMouseLeave={handleMouseLeave} className="book-info" component={Card} sx={{position: 'relative'}}>
            <Box  className="csstransforms3d" sx={{mr: 3}}>
                <Box className="books">
                    <Box style={{background: null}} className="book">
                        <img 
                            height={182} 
                            style={{maxWidth: 100}} 
                            src={cover || require('../assets/livre.jpg')} 
                            alt="Guide de l’investisseur" 
                        />
                    </Box>
                </Box>
            </Box>
            <Box sx={{ml:1, position: 'relative'}} className="description">
                { title ? (title.length > 20 ? 
                     <Tooltip arrow title={title}>
                         <Box sx={{overflow: 'hidden'}}>
                             <Typography variant="subtitle1">
                                {title.slice(0, 20) + '...'}
                             </Typography>
                         </Box>
                     </Tooltip>
                    : 
                    (<Typography variant="subtitle1">
                    {title}
                    </Typography>)
                    ): 'Title'}
                {time &&
                <Box sx={{m:1}} color="text.secondary">
                    <small><time>{time}</time></small>
                </Box>}
                <Box sx={{position: 'absolute', bottom:0}}>
                    <Box sx={{flexGrow: 1, mr:1}}>
                        <Button 
                            {...(
                                props.open ? 
                                {

                                }:
                                {
                                    href: link,
                                    target: "_blank" 
                                }
                            )}
                            variant="contained"
                            size="small"
                            children={text.home.frame.button.open}
                            onClick={props.open}
                        />
                    </Box>
                </Box>
            </Box>
            {(props.action && values.actionButton) &&
                        <IconButton
                            onClick={props.action}
                            sx={{position: 'absolute', bottom:'5px', right: '5px'}}
                        >
                                <MoreVertIcon/>
                        </IconButton>}
        </Box>
    );
}

export default Book;