import {
    Box, Stack, Typography
} from '@mui/material'
import React from 'react';
import TextEditorContent from './views/TextEditorContent';
import TextEditorHeader from './views/TextEditorHeader';
import TextEditorNavLeft from './views/TextEditorNavLeft';

export const TextEditorProps = React.createContext(null);

export default function TextEditor (props) {
    const [values, setValues] = React.useState({
        openNavLeft: false,
        fullScreen: false,
    });
    const handleChangeProps = (prop, value) => event => setValues({
        ...values,
       ...( typeof prop === 'object' ? prop : {[prop]: value})
    });
    return (
        <TextEditorProps.Provider value={[values, handleChangeProps]}>
            <Box>
                <Stack
                    direction="row"
                    display="flex"
                    flex={1}
                    height='100vh'
                >
                    <Box
                        sx={{
                            display: 'flex',
                            flex: values.openNavLeft ? .3 : 0,
                            overflow: 'hidden',
                            transition: theme => theme.transitions.create('flex', {
                                easing: theme.transitions.easing.sharp,
                                duration: theme.transitions.duration.leavingScreen,
                            }),
                        }}
                    >
                        <TextEditorNavLeft/>
                    </Box>
                    <Box
                    sx={{
                        display: 'flex',
                        flex: 1,
                        
                    }}
                    >
                        <Box
                            sx={{
                                height: '100%',
                                display: 'block',
                                width: '100%'
                            }}
                        >
                            <TextEditorHeader/>
                            <TextEditorContent/>
                        </Box>
                    </Box>
                </Stack>
            </Box>
        </TextEditorProps.Provider>
    );
}