import React, { useState, useRef } from 'react';
import {
    Box,
    Typography,
    MenuItem,
    Checkbox,
    FormControlLabel,
    Zoom
} from '@mui/material';
import '../styles/paper.css';
import extensionBase from '../config/fileExtensionBase';
import questionIcon from '../icons/icons8-point-d\'interrogation-48.png';
import ImgToIcon from '../icons/ImgToIcon';
import FormInputTheme from '../config/FormInputTheme';
import CropText from './CropText';
import MenuOptions from './MenuOptions';

export default function Paper (props) {
    const { image, link, ext, options, action, onSelected, infos, label, noteStyle } = props;
    const title = label || 'le titre du mon fichier';
    const img = image ? 
    <Box 
        component="img" 
        src={img} 
        alt={img}
        sx={{
            display: 'flex', 
            flex: 1, 
            width: '100%', 
            height: '100%'
        }}
    /> : 
    <ImgToIcon
        size={50}
        src={(
            extensionBase
            .find(item => 
                ~item.exts.indexOf(ext)
            ) || {}).icon || questionIcon
        }
    />

    return (
        <Box sx={{
            display: 'inline-block',
            position: 'relative',
            p: 1,
        }}>
            <SelectLayer
                options={options}
                link={link}
                action={action}
                onSelected={onSelected}
                infos={infos}
            />
            <Box sx={{
                    display: 'flex',
                    justifyContent: 'center',
                    alignItems: 'center',
                    flex: 1,
                    width: '100%',
                    height: '100%',
                    flexDirection: 'column',
                }}>
                    <Box 
                    className="note"
                    sx={{
                        width: 90,
                        height:120,
                        '&:before': {
                            borderColor: theme => `#fff ${theme.palette.background.default} #bbb #ddd`,
                            ...(noteStyle || {}),
                        }
                    }}
                >
                    <Box sx={{
                        display: 'flex',
                        justifyContent: 'center',
                        alignItems: 'center',
                        flex: 1,
                        width: '100%',
                        height: '100%',
                    }}>
                        {img}
                    </Box>
                </Box>
                <Box sx={{
                        display: 'flex',
                        justifyContent: 'center',
                        alignItems: 'center',
                        flex: 1,
                        width: 90,
                    }}
                    component={Typography}
                    variant="caption"
                    color="text.secondary"
                    align="center"
                    >
                    {title.length > 16?
                    (<CropText
                        len={16}
                    >
                        {title}
                    </CropText>):title
                }
                </Box> 
            </Box>
        </Box>
        
    )
}

function SelectLayer (props) {
    const [selected, setSelected] = useState(false);
    const [showMenu, setShowMenu] = useState(false);
    const [contextMenu, setContextMenu] = React.useState(null);
    const aRef = useRef();
    return (
        <FormInputTheme>
            <Box 
                sx={{
                    position: 'absolute', 
                    width: '100%',
                    height: '100%',
                    top: 0, 
                    left: 0,
                    zIndex: 100,
                }}
                onMouseEnter={() => setShowMenu(true)}
                onMouseLeave={() => setShowMenu(false)}
                onContextMenu={event => {
                    event.preventDefault();
                    setContextMenu(
                      contextMenu === null
                        ? {
                            mouseX: event.clientX + 2,
                            mouseY: event.clientY - 6,
                          }
                        : null,
                    );
                  }}
            >
            <Zoom in={showMenu}>
                <FormControlLabel
                    control={
                        <Checkbox
                            checked={selected}
                            onChange={() => {
                                const newVal = !selected;
                                setSelected(newVal);
                                if(typeof props.onSelected === 'function')
                                    props.onSelected(newVal, newVal && props.infos);
                            }}
                            sx={{
                                color: theme =>  theme
                                .palette.mode === 'dark' ? 
                                '#0095C9' : theme.palette
                                .primary.main
                            }}
                        /> 
                    } 
                    sx={{
                        position: 'absolute',
                        top: 0, 
                        left: 0,
                        zIndex: 102,
                    }}
                />
            </Zoom> 
                <MenuItem 
                    selected={selected} 
                    onClick={() => aRef.current.click()}
                    sx={{
                        width: '100%',
                        height: '100%',
                    }}
                    children={
                        <a 
                            ref={aRef}
                            target="_blink"
                            onClick={props.action}
                            href={props.link}
                        />
                    }
                />
            </Box>
            <MenuOptions
                options={props.options}
                open={contextMenu !== null}
                onClose={() => {
                    setContextMenu(null);
                  }}
                anchorReference="anchorPosition"
                anchorPosition={
                  contextMenu !== null
                    ? { top: contextMenu.mouseY, left: contextMenu.mouseX }
                    : undefined
                }
            />
        </FormInputTheme>
    )
}