import { Tooltip } from '@mui/material';
import propTypes from 'prop-types';
export default function CropText (props) {
    const { len, pad, padType, tooltip} = props;
    const text = props.text || props.children;
    const croper = padType === 'left' ?
    text.slice(0, len) + pad :
    padType === 'right' ?
    pad + text.slice(-text) :
    text.slice(0, len/2) + pad + text.slice(-len/2);
    return (
        tooltip ? 
        <Tooltip
            arrow
            describeChild
            title={text}
        ><span>{croper}</span></Tooltip> : croper)
} 

CropText.defaultProps = {
    len: 0,
    text: '',
    children: '',
    pad: '...',
    padType: 'middle',
    tooltip: true,
}

CropText.propTypes = {
    len: propTypes.number,
    text: propTypes.string,
    pad: propTypes.string,
    children: propTypes.string,
    padType: propTypes.oneOf(['left', 'right', 'middle']),
    tooltip: propTypes.bool,
}
