import { useEffect, useRef, useState } from 'react';
import { 
    Box, 
    Card, 
    CardActions, 
    CardContent, 
    CardHeader, 
    Typography, 
    useTheme,
    Button,
    Checkbox, 
    FormControl, 
    FormControlLabel,
    Avatar, 
    Divider,
    Snackbar,
    Alert,
    IconButton,
    AlertTitle,
    FormHelperText
} from '@mui/material';
import LockRoundedIcon from '@mui/icons-material/LockRounded';
import { Link, useNavigate } from 'react-router-dom';
import FormInputTheme from '../../config/FormInputTheme';
import AdminPanelSettingsRoundedIcon from '@mui/icons-material/AdminPanelSettingsRounded';
import useAxios from 'axios-hooks'
import serverPath from '../../services/serverPath';
import LoadingButton from '@mui/lab/LoadingButton';
import TextFieldController from '../../components/TextFieldController';
import regExpBase from '../../config/regExpBase';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import { useSession } from '../../services/globalConfig';
import refStructObj from '../../services/refStructObj';
import config from '../../config/app.json';

export default function Login (props) {
    const [server, refetch, cancelRequest] = useAxios(LOGIN_URI, {manual: true});
    const [, {setSession}] = useSession();
    const [values, setValues] = useState({
        checking: [],
        snackOpen: false
    });
    const theme = useTheme();
    const fields = {
        email: useRef(null),
        password: useRef(null),
    };
    const stayAuth = useRef(null);
    const navigateTo = useNavigate();
    const color = theme.palette.mode === 'dark' ? 'inherit' : 'primary';
    const handleSendForm = event => {
        event.preventDefault();
        const error = Object.keys(fields).map( field =>  !fields[field].current ? field : null).filter(el => el);
        if(error.length)
            setValues({...values, checking: [...error]});
        else refetch({
                data: {
                    email: fields.email.current, 
                    password: fields.password.current
                },
                method: 'post'
            });
    }
    const handleCloseSnack =  () => setValues({...values, snackOpen: false});

    useEffect(() => {
        if(server.data) {
            setSession('user', 
                refStructObj(
                    server.data, 
                    config.server.refkeys
                )
            );
            navigateTo('/home');
        }
        if(server.error)
            setValues({...values, snackOpen: true});
        return server.loading ? cancelRequest : (()=>{});
    },[server.data, server.error]);
    return (
        <Box
            sx={{
                minHeight: 500,
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                flex: 1
            }}
        >
            <Box
                component={Card}
                elevation={0}
                sx={{
                    minWidth: 350,
                    minHeight: 400,
                    border: theme => `1px solid ${theme.palette.divider}`
                }}
                onKeyDown={event => event.keyCode === 13 && handleSendForm(event)}
            >
                <CardHeader
                    title={
                        <Typography variant="h5" 
                            color={color}
                        >
                            Authentification
                        </Typography>
                    }
                />
                <FormInputTheme>
                    <CardContent>
                        <Divider textAlign="left">
                            <Avatar>
                                <AdminPanelSettingsRoundedIcon />
                            </Avatar>
                        </Divider>
                        <Box component="form" onSubmit={handleSendForm}>
                            <Box>
                                <TextFieldController
                                    label="Adresse électronique"
                                    size="small"
                                    margin="dense"
                                    type="email"
                                    fullWidth
                                    regExp={regExpBase.email}
                                    checking={!!values.checking.find(el => el === 'email')}
                                    ref={fields.email}
                                    helperTextError="email invalide"
                                    //color={color} 
                                />
                            </Box>
                            <Box>
                                <TextFieldController
                                    label="Mot de passe"
                                    size="small"
                                    margin="dense"
                                    ref={fields.password}
                                    fullWidth
                                    type="password"
                                    checking={!!values.checking.find(el => el === 'password')}
                                    regExp={/.+/}
                                    //color={color}
                                />
                            </Box>
                            <Box>
                                <Typography align="right" variant="body2">
                                    <Box 
                                        component={Link} to={'/forgetpassword'}
                                        sx={{
                                            textDecoration: 'none',
                                            color: theme => theme.palette.primary.main,
                                            font: theme => theme.typography.body2.font
                                        }}
                                    > Mot de passe oublié ?
                                    </Box>
                                </Typography>
                            </Box>
                            <Box>
                                <FormControl>
                                    <FormControlLabel
                                        value="left"
                                        control={<Checkbox inputRef={stayAuth} />}
                                        label="Rester connecté"
                                        labelPlacement="end"
                                    />
                                </FormControl>
                            </Box>
                        </Box>
                    </CardContent>
                </FormInputTheme>
                <CardActions>
                    <Button 
                        LinkComponent={Link} 
                        to="/signup" sx={{flexGrow: 1, mx:1}} 
                        size="small" 
                        color={color}>s'inscrire</Button>
                    <LoadingButton 
                        sx={{flexGrow: 1, mx:1}} 
                        startIcon={<LockRoundedIcon/>}
                        size="small" variant="outlined" 
                        type="submit"
                        LinkComponent="input"
                        loading={server.loading}
                        onClick={handleSendForm}
                        color={color}>connexion</LoadingButton>
                </CardActions>
            </Box>
            <Snackbar
                anchorOrigin={{
                    vertical: 'bottom',
                    horizontal: 'center'
                }}
                onClose={handleCloseSnack}
                open={values.snackOpen}
                autoHideDuration={8000}
            >
                <Alert
                     severity="error"
                     children={server.error && server.error.message.toString()}
                     action={
                        <IconButton size="small"
                        onClick={handleCloseSnack}
                        >
                            <CloseRoundedIcon/>
                        </IconButton>
                     }
                >
                    <AlertTitle>
                        Erreur de connexion
                    </AlertTitle>
                    <div>
                    </div>
                    <FormHelperText>
                        {server.error && server.error.message.toString()}
                    </FormHelperText>
                </Alert>
            </Snackbar>
        </Box>
    )
}

const LOGIN_URI = serverPath('api/auth/login');