import DeleteIcon from "@mui/icons-material/Delete";
import { Avatar, Box, CircularProgress, Divider, IconButton, ListItem, ListItemAvatar, ListItemButton, ListItemText, Tooltip, Typography } from "@mui/material";
import { Fragment, useEffect, useLayoutEffect, useState } from "react";
import FragmentOrbit from "../../components/FragmentOrbit";
import { getFileName } from "../../treatments/getFileExtension";
import CancelIcon from '@mui/icons-material/Cancel';
import bytesConverter from "../../treatments/bytesConverter";
function UploadProgress (props) {
    const [values, setValues] = useState({
        progress: props.defaultValue * 100,
        name: props.name || getFileName(props.file.name),
        loaded: bytesConverter(parseFloat(props.loaded)),
        total: bytesConverter(parseFloat(props.total))
    });

    const handleRemoveAndCancel = (event)  => {
        if(props.state !== 'finish') 
                props.cancel();     
        props.remove();
    };

    useEffect(() => {
        props.xhr.upload.onprogress = (event) => {
            const { loaded, total } = event;
            setValues({
                ...values, 
                progress: (loaded / total) * 100,
                loaded: bytesConverter(loaded),
                total: bytesConverter(total)
            });
        }
    },[values.progress]);

    useLayoutEffect(() => {
        if(props.state === 'finish') 
            setValues({
                ...values, 
                progress: 100,
                loaded: bytesConverter(values.total),
                total: bytesConverter(values.total)
            });
    },[])

    return(
        <Fragment>
            <Box component={ListItem}
            secondaryAction={
                <Tooltip  
                enterDelay={2000}
                arrow title={props.state === 'finish' ? "supprimer dans historique" : "annuler"}>
                    <IconButton 
                        onClick={handleRemoveAndCancel}
                    edge="end">
                        {
                        props.state === 'finish' ?
                        (<DeleteIcon />) : (<CancelIcon />)
                        }
                    </IconButton>
                </Tooltip>
            }
            >
                <ListItemAvatar>
                <Avatar sx={{bgcolor: 'transparent', position: 'relative', display: 'inline-flex'}}>
                    <CircularProgress variant="determinate" 
                        value={props.state === 'finish' ? 100 : values.progress}
                    />
                    <Box
                        sx={{
                        top: 0,
                        left: 0,
                        bottom: 0,
                        right: 0,
                        position: 'absolute',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        }}
                    >
                        <Typography variant="caption" component="div" color="text.secondary">
                        {`${Math.round(values.progress)}%`}
                        </Typography>
                    </Box>
                </Avatar>
                </ListItemAvatar>
                <FragmentOrbit arrow  component={ values.name.length > 30 ? Tooltip : null } title={values.name}>
                        <ListItemText 
                            primary={values.name.length > 25 ? values.name.slice(0, 25) + '...' : values.name } 
                            secondary={
                                values.loaded +'/'+ values.total
                            }
                        />
                </FragmentOrbit>
            </Box>
            {props.uploadLength - 1 !== props.currentIndex &&
            <Divider variant="inset" component="li" />
            }
        </Fragment>
    )
    
}

export default UploadProgress;