import { useLayoutEffect, useState } from "react";

export default function useSystemTheme(props) {
    const darkThemeMediaquery = window
    .matchMedia("(prefers-color-scheme: dark)");
    const [theme, setTheme] = useState(
        darkThemeMediaquery.matches ? 'dark': 'light'
        );
    const handleChange = event => setTheme(
    event.target.matches ? 'dark': 'light'
    );
    useLayoutEffect(()=> {
        darkThemeMediaquery
        .addEventListener('change', handleChange);
        return () => darkThemeMediaquery
        .removeEventListener('change', handleChange);
    },[theme]);
    return(theme)
}
