import { Drawer, Box, useMediaQuery, Fade, Slide, Typography } from "@mui/material";
import React, { useCallback, useState, useEffect, Fragment } from "react";
import { Navigate } from "react-router-dom";
import { useData } from "../treatments/globalData";

function AppContentBox({children, backLink}) {
    const [open, setOpen] = useState({value: null, redirect: false});
    const { screen } = useData();
    const isMiddleScreen = true;// useMediaQuery(screen);
    const handleOpen = useCallback((openDrawer)=> {
        setOpen({...open, value: openDrawer});
    }, [open]);

    const cloneChildren = React.Children.toArray(children).map((elem, index) => (
        React.cloneElement(elem, {key: index, handleBoxContent: handleOpen })
    ))
    useEffect(() => {
        if(open.value === null) handleOpen(true);
        if(open.value === false) setOpen({...open, redirect: true})
    }, [open.value, handleOpen, open]);

    return(
        <Slide direction="up" in={!!open.value}>
            <Box>
                <Box sx={{height:'100vh', width:'100vw', overflow: isMiddleScreen ? 'hidden' : ''}}>{cloneChildren}</Box> 
            {open.redirect && <Navigate to={backLink || '/'} />}
            </Box>
        </Slide>
    );
    
}
export default AppContentBox;