import {useState, useRef, Fragment, useContext, useEffect} from 'react';
import Modal from '@mui/material/Modal';
import Typography from '@mui/material/Typography';
import Box from '@mui/material/Box';
import FileUploadIcon from '@mui/icons-material/FileUpload';
import { Button, ButtonGroup, IconButton, Snackbar } from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import { getFileExtension, getFileName } from '../../treatments/getFileExtension';
import LocalSeeIcon from '@mui/icons-material/LocalSee';
import VideocamIcon from '@mui/icons-material/Videocam';
import AudiotrackIcon from '@mui/icons-material/Audiotrack';
import ArticleIcon from '@mui/icons-material/Article';
//import QuizIcon from '@mui/icons-material/Quiz';
import fileExtensionBase from '../../config/fileExtensionBase';
import CloseIcon from '@mui/icons-material/Close';
import { WorkSpaceContext } from './WorkSpace';
import serverPath from '../../../../../services/serverPath';
import { CurrentSession } from '../../components/Auth';
import bytesConverter from '../../treatments/bytesConverter';

const formats = [
  { label: 'photo', title: 'format images', icon: <LocalSeeIcon/> },
  { label: 'video', title: 'format videos', icon: <VideocamIcon/> },
  { label: 'audio', title: 'format audios', icon: <AudiotrackIcon/> },
  { label: 'doc', title: 'format documents', icon: <ArticleIcon/> },
  //{ label: 'video', title: 'format inconnu', icon: <QuizIcon/> }   
];

function FileForm() {
  const [contextValues, actions] = useContext(WorkSpaceContext);
  const inputFileField = useRef(null);
  const inputTextField = useRef(null);
  const [currentSession] = useContext(CurrentSession);
  const [values, setValues] = useState({
    ...(contextValues.fileForm ? ({
      file: contextValues.fileForm.file,
      name: getFileName(contextValues.fileForm.file.name)
    }) : ({
      file: null,
      name: 'ouvrir un fichier',
    })),
     
      messageSnak: '',
      alertSnack : false
  })
  
  const handleOpenFile = (event) => {
        inputFileField.current.click();
  }
  const handleSetInputFocus = (event) => {
      inputTextField.current.focus();
      inputTextField.current.select();
  }
  const handleInputFocus = (event) => {
      setValues({...values, name: values.name || getFileName(values.file.name) })
  }
  const handleOpenChange = (event) => {

        const [file] = event.target.files;
        if(file)
            setValues({...values, file: file, name: getFileName(file.name)})
  }
  const handleChangeName = (event) => {
      setValues({...values, name: event.target.value});
  };

  const handleSetFileForUpload = () => {
    
      const fileExt = getFileExtension(values.file.name);
      const fileName = (values.name ? values.name.trim() ? 
      values.name.trim() : getFileName(values.file.name) : 
      getFileName(values.file.name)); //+ '.' + fileExt;

      const index = ['doc', 'photo', 'video' ].findIndex((item) => 
      (~fileExtensionBase[item].indexOf(fileExt)));

      console.log(contextValues.keys.split(';')[index]);

      const route = serverPath('api/stuff/workspace');
      const xhr = new XMLHttpRequest();
      xhr.open('post', route);
      xhr.setRequestHeader('Authorization', `Bearer ${currentSession.token}`);
      const form = new FormData();
      form.append('filename', fileName);
      form.append('userId', currentSession.id);
      form.append('path', contextValues.keys.split(';')[index]);
      form.append('file', values.file);

      xhr.upload.onprogress = (event) => {
          const { loaded, total } = event;
          dataRequest.loaded = loaded;
          dataRequest.total = total;
          dataRequest.defaultValue = loaded / total;
      }

      xhr.onloadend = (event) => {
        
          //if(xhr.status >= 200 && xhr.status < 400)
          setValues({
            file: null,
            name: 'ouvrir un fichier',
            messageSnak: `Téléchargement de ${values.name.length > 35 ? values.name.slice(0, 35) + '...' : values.name } terminé`,
            alertSnack : true,
        });
    }

      const dataRequest = {
        xhr: xhr,
        index: contextValues.uploads.length,
        file: values.file,
        error: null,
        state: 'start',
        defaultValue: 0,
        delete: false,
        send() {
          xhr.send(form);
        },
        cancel() {
          xhr.abort();
        }
      }
      const currentUploads = [...contextValues.uploads];
      currentUploads.push(dataRequest);
      actions.handleChangeProps({uploads: currentUploads, fileForm: false });

        setValues({
          file: null,
          name: 'ouvrir un fichier',
          messageSnak: `${values.name.length > 35 ? values.name.slice(0, 35) + '...' : values.name } en téléchargement `,
          alertSnack : true,
      });
  }

  useEffect(() => {
      if(contextValues.fileForm && !values.file) {
        setValues({
          ...values, 
          file: contextValues.fileForm.file, 
          name: getFileName(contextValues.fileForm.file.name)
        })
     }
  },[contextValues.fileForm, values.file]);

  return (
    <Fragment>
      <Modal
        disableAutoFocus
        open={Boolean(contextValues.fileForm)}
        aria-labelledby="server-modal-title"
        aria-describedby="server-modal-description"
        sx={{
          display: 'flex',
          p: 1,
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        <Box
          sx={{
            position: 'relative',
            width: 500,
            bgcolor: 'background.paper',
            height:200,
            boxShadow: (theme) => theme.shadows[10],
            p: 3,
          }}
        >
          <input ref={inputFileField} hidden type="file" onChange={handleOpenChange}/>
          <IconButton 
            sx={{position: 'absolute', top: 10, right: 10}}
            onClick={() => {
              actions.handleChangeProps({fileForm: false})
            }}
            >
                <CloseIcon />
          </IconButton>
          <Typography  variant="h6"  color="primary">
            Ajouter un fichier
          </Typography>
          <Box sx={{ height: 110, pt:2}}>
            <ButtonGroup fullWidth variant="outlined">
                    <Button disabled sx={{flexGrow: 1}}>
                        <Box 
                        component="input"
                        sx={{
                            border: 'none',
                            fontSize: theme => theme.typography.body1.fontSize,
                            color: theme => theme.palette.text.secondary,
                            text: 'left',
                            outline: 0,
                            width: '100%',
                            background: 'none'
                            
                        }} 
                        value={values.name} 
                        onChange={handleChangeName}
                        ref={inputTextField}
                        onBlur={handleInputFocus}
                        readOnly={Boolean(!values.file)}
                        /> 
                    </Button>
                    {
                        values.file &&
                        (<Button sx={{width: 50}} onClick={handleSetInputFocus}>
                            <EditIcon/>
                        </Button>)}
                    <Button onClick={handleOpenFile} sx={{width: 150}} children="ouvrir" endIcon={<FileUploadIcon/>} variant="contained" />
            </ButtonGroup>
            <Box sx={{color: 'text.secondary', pt:1}}>
                <Typography
                >
                   { 
                   values.file &&
                    formats.filter((item) => ~fileExtensionBase[item.label].indexOf(getFileExtension(values.file.name)))
                    .map((item, index) => (
                        <Fragment key={index}>
                            {item.icon} <span style={{position: 'relative', top: '-5px'}}>{values.file.type
                            }; {bytesConverter(values.file.size)}
                            </span>
                        </Fragment>
                    ))
                }
               </Typography>
            </Box>
          </Box>
          <Box>
            <Button 
              variant="contained"
              onClick={handleSetFileForUpload}
              disabled={!values.file}
            >Téléchargez</Button>
          </Box>
        </Box>
      </Modal>
      <Snackbar
        open={Boolean(values.alertSnack)}
        autoHideDuration={2000}
        onClose={() => {
          setValues({...values, alertSnack: false, messageSnak: '' })
      } }
      anchorOrigin={{
          vertical: 'bottom',
          horizontal: 'right'
      }}
      message={values.messageSnak}
      action={
          <IconButton
              size="small"
              color="inherit"
              onClick={() => {
                setValues({...values, alertSnack: false, messageSnak: ''})
              }}
          >
              <CloseIcon/>
          </IconButton>
      }
      />        
    </Fragment>
  );
}

export default FileForm;