import propTypes from 'prop-types'
import { useEffect } from 'react';
import { useState } from 'react'

function WriteSlowlyText(props) {
    const [text, setText] = useState('');
    const handleWriteText = () => {
        if(text === props.text) window.setTimeout(
            () => {
               props.action();
            }, props.endDelay);
        else return window.setTimeout((params) => {
            setText(text + props.text.charAt(text.length));
        }, props.time / text.length);
    }

    useEffect(() => {
        const writeText = window.setTimeout(handleWriteText, props.delay);
        return () => {
            if(writeText) window.clearTimeout(writeText);
        }
    })
    useEffect(() => {
        if(props.initRef) {
            props.initRef.current = setText;
        }
    }, [props.initRef])
    return text;
}

WriteSlowlyText.defaultProps = {
    time: 1000,
    text: '',
    delay: 0,
    endDelay: 0,
    action(){},
    initRef: null
}
 WriteSlowlyText.propTypes = {
     time: propTypes.number,
     action: propTypes.func,
     delay: propTypes.number,
     endDelay: propTypes.number,
     initRef: propTypes.object
 }
 export default WriteSlowlyText;