import { Editor as TinymceEditor } from '@tinymce/tinymce-react';
import {
    Backdrop,
    Box, CircularProgress
} from '@mui/material';
import init from '../config/init';
import { useState } from 'react';

export default function Editor (props) {
    const [values, setValues] = useState({
        loading: true,
    })
    return (
        <Box>
            <TinymceEditor
                //tinymceScriptSrc={`${process.env.PUBLIC_URL}/scripts`}
                init={{
                    ...init,
                    language: 'fr_FR',
                }}
                initialValue=""
                scriptLoading={{ async: true }}
                onLoadContent={() => setValues({...values, loading: false})}
            />
            <Backdrop
                sx={{
                color: '#fff',
                zIndex: (theme) => theme.zIndex.drawer + 1,
                backdropFilter: 'blur(15px)',
                }}
                open={values.loading}
            >
                <CircularProgress
                    color="inherit"
                    size="small"
                    sx={{
                        width: 25,
                        height: 25
                    }}
                />
            </Backdrop>
        </Box>
    );
}

