import {
    ThemeProvider,
    useTheme,
    createTheme,
} from '@mui/material';
import propTypes from 'prop-types';

export default function FormInputTheme ({children, mode:defaultMode}) {
    const currentTheme = useTheme();
    const mode = defaultMode === 'auto' ? currentTheme.palette.mode : defaultMode;
    const theme = createTheme({
        ...currentTheme,
        palette: {
           // ...currentTheme.palette,
            mode,
            ...(mode === 'dark' ? {
                primary: {main: '#0095C9'},
            } : {
                primary: {main: currentTheme.palette.primary.main},
            }),
            background: currentTheme.palette.background,
        },
    });
    return (
        <ThemeProvider theme={theme}>
           {children}
        </ThemeProvider>
    )
}

FormInputTheme.defaultProps = {
    mode: 'auto',
}

FormInputTheme.propTypes = {
    mode: propTypes.oneOf(['dark', 'light', 'auto']),
}
