import React, { useState } from 'react';
import {
    Drawer, List, ListItem, ListItemButton, ListItemText
} from '@mui/material';
import FormSend from './FormSend';

export default function SendNav (props) {
    const {open, file} = props;
    const [values, setValues] = useState({
        app: null,
        label: '',
    })
    return (
        <React.Fragment>
            <FormSend
                open={!!values.app}
                app={values.app}
                title={values.label}
                file={file}
                onClose={() => setValues({})}
            />
            <Drawer
              anchor="bottom"
              open={open}
              onClose={props.onClose}
              BackdropProps={{
                sx:{
                    backdropFilter: 'blur(15px)', 
                }
              }}
            >
              <List>
                {sendOptions.map((item, index) => (
                <ListItem key={index} disablePadding>
                    <ListItemButton sx={{height: 30}}
                        onClick={() => {
                            setValues({...values, label: item.label, app: item.alias});
                            props.onClose();
                        }}
                    >
                        <ListItemText 
                        primaryTypographyProps={{
                            fontSize: 15,
                        }}
                        primary={item.label} />
                    </ListItemButton>
                </ListItem>
                ))}
            </List>
            </Drawer>
        </React.Fragment>
    )
}

const sendOptions = [
    {
        label: 'Archives',
        icon: '',
        alias: 'archives',
    },
    {
        label: 'Mediathèque',
        icon: '',
        alias: 'medialibrary',
    },
];
