import {
    Box,
    Divider,
    Drawer, 
    List, 
    ListItemButton,
    Typography,
    ListItemAvatar,
    ListItemText,
    ListItemIcon,
    Radio,
    Avatar,
    ListSubheader,
    IconButton,
    Toolbar
} from '@mui/material';
import LightModeRoundedIcon from '@mui/icons-material/LightModeRounded';
import NightlightRoundRoundedIcon from '@mui/icons-material/NightlightRoundRounded';
import Brightness4RoundedIcon from '@mui/icons-material/Brightness4Rounded';
import FormInputTheme from '../config/FormInputTheme';
import CloseRoundedIcon from '@mui/icons-material/CloseRounded';
import { useConfig } from '../services/globalConfig';

export default function SettingsNav (props) {
    const [{themeMode, settingsNav}, actions] = useConfig();
    const optionsTheme = [
      {label: 'Clair', icon: LightModeRoundedIcon, value: 'light'},
      {label: 'Sombre', icon: NightlightRoundRoundedIcon, value: 'dark'},
      {label: 'Thème par défaut du système', icon: Brightness4RoundedIcon, value: 'system'}
    ];
    return (
        <Drawer
          anchor="right"
          open={settingsNav}
          onClose={() => actions(null).handleChangeProps({settingsNav: false})}
          {...props}
          BackdropProps={{
            sx:{backdropFilter: 'blur(15px)',}
          }}
        >
          <Box
            sx={{width: 300, p:1}}
          >
              <Box sx={{justifyContent: 'right', display: 'flex'}}>
                <IconButton
                  size="small"
                  onClick={() => actions(null).handleChangeProps({settingsNav: false})}
                >
                  <CloseRoundedIcon/>
                </IconButton>
              </Box>
            <Typography 
              variant="h6"
              fontSize={20}
            >
              Paramètre
            </Typography>
            <Divider/>
            <Box>
            <FormInputTheme>
              <List 
                dense={false}
                sx={{mt: 1}}
                subheader={
                  <ListSubheader component="div">
                    Apparence
                  </ListSubheader>
                }
              >
                {
                  optionsTheme.map((theme, index) => (
                    <ListItemButton 
                      key={index}
                      sx={{height: 50}}
                      onClick={(event) => {
                        event.preventDefault();
                        actions(null).handleChangeTheme(theme.value);
                      }}
                    >
                      
                        <ListItemIcon>
                          <Radio 
                            checked={theme.value === themeMode} 
                            disableRipple={true} 
                            size="small"
                          />
                        </ListItemIcon>
                      <ListItemText
                        primary={theme.label}
                        primaryTypographyProps={{
                          fontSize: 14,
                          m:0, p: 0
                        }}
                      />
                      <ListItemAvatar>
                          <Avatar
                            sx={{ 
                              width: 30, 
                              height: 30, 
                              bgcolor: theme.value === themeMode ? 
                              'primary.main': ''
                            }}
                          >
                            <theme.icon/>
                          </Avatar>
                      </ListItemAvatar>
                    </ListItemButton>
                  ))
                }
              </List>
            </FormInputTheme>
            </Box>
          </Box>
        </Drawer>
    )
}