const SignupProps = createContext(null) ;

export default function Signup () {
    const [values, setValues] = useState({
        step: 0,
        errorFields: [],
    });
    const [{
        data:structure,
        loading: loadingStr,
        error
    }, refetch] = useAxios({url:STR_URI, method: 'get'});
    const fields = {
        lastName: useRef(''),
        middleName: useRef(''),
        firstName: useRef(''),
        email: useRef(''),
        password: useRef(''),
        phoneNumber: useRef(''),
        funcStructure: useRef([]),
    };
    const code = useRef(randomCode({mode: 'num'}));
    const handleCheckStep = progress => () => {
        const errorFields = [];
        if(progress === 'next') {
           steps[values.step].fieldsToCheck.forEach(field => {
                if(
                    Array.isArray(fields[field].current) &&
                    fields[field].current.length  < 2
                ) errorFields.push(field);
                else if(!fields[field].current)
                    errorFields.push(field);
            });
            if(errorFields.length > 0)
                setValues({...values, errorFields});
            else
                setValues({
                    ...values,
                    step: values.step + 1,
                    errorFields: []
                });

        } else {
            if(values.step > 0)
                setValues({...values, step: values.step - 1});
        }
    }
    const theme = useTheme();
    const color = theme.palette.mode === 'dark' ? 'inherit' : 'primary';
    const CurrentStep = steps[values.step].module;
    const isErrorField = field => !!values.errorFields.find(error => error === field);
    useEffect(() => {

    })
    return (
        <Box
            sx={{
                minHeight: 500,
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                flex: 1
            }}
        >
            <Box
                component={Card}
                elevation={0}
                sx={{
                    minWidth: 760,
                    minHeight: 500,
                    mt: 5,
                    border: theme => `1px solid ${theme.palette.divider}`
                }}
            >
                <CardHeader
                    title={
                        <Typography variant="h5"
                            color={color}
                        >
                            Inscription
                        </Typography>
                    }
                />

                <FormInputTheme>
                    <StepLevel
                        steps={steps}
                        step={values.step}
                    />
                    <CardContent
                        sx={{
                            display: 'flex',
                            alignItems: 'center',
                            minHeight: 250,
                            '& hr': {
                                mx: 1.5,
                            },
                    }}
                    ><SignupProps.Provider
                    value={{
                        fields,
                        structure,
                        isErrorField,
                        refetch,
                        code
                    }}
                    >
                    {error ?
                    (<Alert
                        severity="error"
                        sx={{
                            width: 700
                        }}
                        action={
                            <Button
                                size="small"
                                LinkComponent={Link}
                                to="/home"
                                sx={{textTransform: 'none'}}
                            >Retourner à l'accueil</Button>
                        }
                    >
                        <AlertTitle

                        >
                            Impossible de s'inscrire
                        </AlertTitle>
                        <span>
                            Impossible de soumettre cette requête,
                            une erreur est survenue lors de la creation du compte
                            réessayez ultérieurement
                        </span>
                        <FormHelperText>
                            {error.message} : {error.code}
                        </FormHelperText>
                    </Alert>) : (<CurrentStep/>)}
                    </SignupProps.Provider>
                    </CardContent>
                    <CardActions
                        sx={{justifyContent: 'right', display: 'flex'}}
                    >
                        <Slide direction="left" in={values.step < 3}>
                            <Button
                                size="small"
                                color={color}
                                to="/"
                                LinkComponent={Link}
                                sx={{mx: 1}}
                            >Annuler</Button>
                        </Slide>

                        <Button
                            size="small"
                            color={color}
                            disabled={!values.step}
                            variant="outlined"
                            onClick={handleCheckStep('previous')}
                        >precedent</Button>
                        <Button
                            size="small"
                            color={color}
                            variant="outlined"
                            disabled={!!error ||( steps.length -1 === values.step)}
                            onClick={handleCheckStep('next')}
                        >suivant</Button>
                    </CardActions>
                </FormInputTheme>
            </Box>
            <Backdrop
                open={loadingStr}
                sx={{
                    justifyContent: 'center',
                    alignItems: 'center',
                    color: '#fff',
                    zIndex: (theme) => theme.zIndex.drawer + 1,
                    backdropFilter: 'blur(15px)',
                }}
                children={
                    <CircularProgress
                        color="inherit"
                        size="small"
                        sx={{
                            width: 25,
                            height: 25
                        }}
                    />
                }
            />
        </Box>
    )
}

