function ValidateIdentity() {
    const { fields, refetch, code } = useContext(SignupProps);
    const [values, setValues] = useState({error: false});
    const stayed = useRef(null);
    const navigateTo = useNavigate();
    const [, sessionActions] = useSession();
    const handleSignup = codeInfield => {
        
        if(code.current === codeInfield) {
            if(values.error) setValues({...values, error: false});
            const data = {
                fname: fields.firstName.current,
                lname: fields.lastName.current,
                mname: fields.middleName.current,
                email: fields.email.current,
                phoneCell: fields.phoneNumber.current,
                password: fields.password.current,
                grade: {
                    grade : fields.funcStructure.current[0],
                    role : fields.funcStructure.current[1],
                },
            };
            refetch({
                data,
                method: 'post',
                url: SIGNUP_URI,
            }).then(() => {
                if(stayed.current.checked) {
                    refetch({
                        data: {
                            email: data.email,
                            password: data.password,
                        },
                        method: 'post',
                        url: LOGIN_URI,
                    }).then(result => {
                        sessionActions.setSession(
                            'user',
                            refStructObj(
                                result.data,
                                config.server.refkeys
                                )
                        );
                        navigateTo('/home');
                    })
                } else navigateTo('/login');
            }).catch(error => {
                console.log(error);
            })
        } else {
            setValues({...values, error: true});
        }
    };
    return (
        <Fade in={true}>
          <Box>
            <Box
                sx={{
                    flewGrow: 1,
                    display: 'flex',
                    justifyContent: 'center',
                    alignItems: 'center',
                    flex: 1,
                    flexDirection: 'column',
                }}
            >
                <CodeField
                    action={handleSignup}
                    error={values.error}
                />
                {values.error &&
                <FormHelperText>
                    <Typography variant="caption" component="span" color="error">
                        Le code de validation incorrecte
                    </Typography>
                </FormHelperText>}
            </Box>
            <Box sx={{
              my: 1,
              maxWidth: 700
            }}>
              <Typography color="text.secondary" variant="body2">
                <HighlightingText
                    replace='#email#'
                    by={fields.email.current}
                    Wrapper={Typography}
                    wrapperProps={{
                      component: "span",
                      variant: "h6",
                      color: 'primary',
                      fontSize: 15,
                    }}
                >
                    Nous avons envoyé un code à l'adresse email #email#, veuillez l'entrer
                    depuis la zone ci-haute pour confirmer l'existance de l'adresse enfin
                    de certifier la soumission de votre demande d'inscription.
                </HighlightingText>
              </Typography>
              <FormControlLabel
                value="stayed"
                control={<Checkbox size="small" inputRef={stayed} />}
                label="se connecter après l'inscription"
                labelPlacement="end"
              />
              <Timer/>
            </Box>
          </Box>
        </Fade>
    )
}

const StructureList = forwardRef((props, ref) => {
    const { structure } = props;
    const { fields, isErrorField } = useContext(SignupProps);
    const [value, setValue] = useState(!!(fields.funcStructure.cu || {})[0]);
    const funcs = structure && Object.keys(structure).map((func) => ({label: func, value: func }));
    const [funcLabel] = value || [];
    const sectors = funcLabel && structure[funcLabel].map((sec) => ({label: sec, value: sec }));
    const funcLocalRef = useRef(null);
    const secLocalRef = useRef(null);
    const handleChange = field => (event, newValue) => {
        if(field === 'func') {
            setValue([
                newValue,
                structure[newValue].length === 1 ? structure[newValue][0] : undefined
            ]);
            funcLocalRef.current = newValue;
        }
        if(field === 'sec') {
            secLocalRef.current = newValue;
            const newValues = [...value];
            newValues[1] = newValue;
            setValue(newValues);
        }
    };
    //const [defaultValuesFunc, defaultValueSec] = fields.funcStructure.current || [];
    useLayoutEffect(() => {
        if(ref) ref.current = value;
    },[value]);
    useLayoutEffect(() => {
        if(ref) ref.current = fields.funcStructure.current.length > 1 ?
        fields.funcStructure.current : value;
    }, [])

    const funcColor = isErrorField('funcStructure') ?
    ( funcLocalRef.current ? 'primary' : 'error')
   : 'primary';
   const secColor = !secLocalRef.current && (sectors || {}).length > 1  ? 'error' : 'primary';
    return ( 
        <React.Fragment>
                {funcs ?
                <SelectOption
                    label="Fonction"
                    options={funcs}
                    onChange={handleChange('func')}
                    disabled={!structure} 
                    size="small" 
                    margin="dense" 
                    fullWidth
                    color={funcColor}
                    //defaultValue={defaultValuesFunc}
                />: <SelectOption label="Fonction" size="small" margin="dense" fullWidth />}
            {funcColor=== 'error' &&
              <FormHelperText>
                <Typography variant="caption" color={funcColor}>
                    champ vide
                </Typography>
              </FormHelperText>
            }
                    {((sectors || {}).length > 1) ?
                    <SelectOption
                        labelId="sector-select-label"
                        label="Secteur"
                        options={sectors}
                        color={secColor}
                        onChange={handleChange('sec')}
                        disabled={!(sectors && sectors.length > 1)} 
                        size="small" 
                        margin="dense" 
                        fullWidth
                        //defaultValue={defaultValueSec}
                    />: <SelectOption label="Secteur" size="small" margin="dense" fullWidth/>}
                    {secColor=== 'error' &&
                    <FormHelperText>
                        <Typography variant="caption" color={funcColor}>
                            champ vide
                        </Typography>
                    </FormHelperText>
                    }
        </React.Fragment>
    )
});

const PasswordValidate = forwardRef((props, ref) => {
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const { isErrorField } = useContext(SignupProps);

    useEffect(() => {
        if(ref) ref.current = null;
    },[]);
    return(
        <React.Fragment>
            <Box>
                <TextFieldController
                    label="Mot de passe"
                    showPasswordProps={showPassword}
                    checking={isErrorField('password')}
                    onToggleShowPassword={(value, callback) => {
                        callback(value);
                        setShowPassword(value);
                    }}
                    margin="dense"
                    fullWidth
                    type="password"
                    size="small"
                    onChange={(event) => {
                        const { value } = event.target;
                        setPassword(regExpBase.password.test(value) ? value : '');
                    }}
                    regExp={regExpBase.password}
                    helperTextError="Le format de mot de passe invalide"
                />
            </Box>
            <Box>
                <TextFieldController
                    label="Confirmer"
                    onToggleShowPassword={(value, callback) => {
                        callback(value);
                        setShowPassword(value);
                    }}
                    showPasswordProps={showPassword}
                    margin="dense"
                    fullWidth
                    type="password"
                    size="small"
                    regExp={'^'+password+'$'}
                    checking={!!(isErrorField('password') && password)}
                    onChange={(event) => {
                        const { value } = event.target;
                        if((password === value) && ref) ref.current = value;
                        else ref.current = null;
                    }}
                    helperTextError="Ce mot de passe est différent du précédent"
                />
            </Box>
        </React.Fragment>
    );
})

const Timer = () => {
    const { fields, refetch, code } = useContext(SignupProps);
    const firstStart = useRef(true);
    const {
        seconds,
        minutes,
        restart,
        isRunning
      } = useTimer({
        expiryTimestamp: getTime(300),
        onExpire: () => {code.current = null},
        autoStart: false,
    });

    const handleCheckEmail = () => {
        const newCode = randomCode({mode: 'num'});
        code.current = newCode;
        refetch({
         url: VALIDATE_URI,
         method: 'post',
         data: {
            key: newCode,
            email: fields.email.current,
         }
        }).then(() => {
            firstStart.current = false;
            restart(getTime(300));
        })
        .catch((error) => {
            console.log(error);
        })
    }

    useEffect(() => {
        handleCheckEmail();
    }, []);

    return (
        <Typography variant="h6" fontSize={14} component="div" paragraph>
            { (isRunning || firstStart.current) ? `le code expire dans ${minutes ? minutes + ':' : ''}${seconds}` :
            <Alert
                severity="warning"
                action={
                    <Button
                        disabled={isRunning}
                        size="small" sx={{textTransform: 'none'}}
                        onClick={handleCheckEmail}
                    >
                        Renvoyer un nouveau code
                    </Button>
                }
            >
                le code de validation envoyé à votre adresse déjà expiré
            </Alert>
            }
        </Typography>
    );
}

const steps = [
    {
        fieldsToCheck: ['lastName', 'firstName', 'middleName', 'funcStructure'],
        module: PersonalIdentity,
    },{
        fieldsToCheck: ['email', 'phoneNumber', 'password'],
        module: AccountIdentity,
    },{
        fieldsToCheck: [''],
        module: ValidateIdentity,
    }
];
const STR_URI = serverPath('/api/auth/init');
const SIGNUP_URI = serverPath('/api/auth/signup');
const LOGIN_URI = serverPath('/api/auth/login');
const VALIDATE_URI = serverPath('/api/auth/validate');
