
import SettingsIcon from '@mui/icons-material/Settings';
import { Fab, useMediaQuery } from '@mui/material';
import { Fragment, useContext } from 'react';
import { useData, useSetting } from '../treatments/globalData';
import { CurrentSession } from './Auth';
import { ProfileNav, SettingNavMobile, SettingOptions } from './Settings';
import SignIn from './SignIn';

function SettingsGlobal() {

    const { screen } = useData();
    const [,action] = useSetting();
    const isMiddleScreen = useMediaQuery(screen);
    const [currentSession] = useContext(CurrentSession);
    return(
        <Fragment>
         { isMiddleScreen ? (
             <Fragment>
                 <ProfileNav/>
             </Fragment>
         ): (
             <Fragment>
                <Fab 
                    color='primary' 
                    sx={{
                        position: 'fixed', 
                        bottom: '15px', 
                        right: '15px',
                        zIndex: theme => theme.zIndex.modal
                    }}
                    onClick={action.onOpen('settingOptions')}
                >
                    <SettingsIcon />
                </Fab>
                <SettingNavMobile/>
             </Fragment>
         ) }
            <SettingOptions/>
            {
            !currentSession &&
            <SignIn/>
            }
        </Fragment>
    )
}

export default SettingsGlobal;