function formatTimer(seconds, graduatTime = 'second', lang) {

    let days     = Math.floor(seconds / (24*60*60));
      seconds -= days    * (24*60*60);
    let hours    = Math.floor(seconds / (60*60));
        seconds -= hours   * (60*60);
    let minutes  = Math.floor(seconds / (60));
        seconds -= minutes * (60);
    return `${parseInt(days) ? parseInt(days) +'j' : '' } ${parseInt(hours) ? String(parseInt(hours)).padStart(2, '0') + ' :' : '' } ${ (String(parseInt(minutes)).padStart(2, '0')) + ' : ' + (String(parseInt(seconds)).padStart(2, '0'))}`.trim();                                                                                
}
export default formatTimer;