import propTypes from 'prop-types';
import React from 'react';

export default function  HighlightingText (props) {
    const {Wrapper, wrapperProps, mode, by, replace, children: text} = props;
    const textsArray = text.split(RegExp(replace));
    const newTextArray = [];
    textsArray.forEach((elem, index, arr) => {
        if(arr[index] && arr[index + 1]) {
            if(mode === 'one' && !index)
                newTextArray.push(elem,
                    <Wrapper
                        children={by}
                        {...wrapperProps}
                    />
                    );
             else if(mode === 'all')
                newTextArray.push(elem,
                    <Wrapper
                        children={by}
                        {...wrapperProps}
                    />
                    );
            else newTextArray.push(elem);
        } else newTextArray.push(elem);
    });


    return (
        <React.Fragment>
            {newTextArray.map((elem, key) => (
                <React.Fragment key={key}>{elem}</React.Fragment>
            ))}
        </React.Fragment>
    )
}

HighlightingText.defaultProps = {
    children: '',
    replace: '',
    by: '',
    mode: 'one',
    wrapperProps: {},
    regExpOption:'',
    Wrapper: (props) => <mark {...props}/>,
}
HighlightingText.propTypes = {
    children: propTypes.string,
    mode: propTypes.oneOf(['one', 'all']),
    //Wrapper: propTypes.func,
    wrapperProps: propTypes.object,
    regExpOption: propTypes.string,
};
