import React, { useEffect, useRef, useState } from 'react';
import ExitToAppRoundedIcon from '@mui/icons-material/ExitToAppRounded';
import { 
    AppBar,
    Dialog,
    Typography,
    IconButton,
    Toolbar,
    Tooltip,
    Box,
    Stack,
    Button,
    DialogContent, 
    DialogActions, 
    Grid, 
    CardMedia, 
    Card,
    ImageList,
    ImageListItem,
    ImageListItemBar,
    CardActionArea,
    Backdrop,
    CircularProgress,
} from '@mui/material';
import TextFieldController from '../../../components/TextFieldController';
import FormInputTheme from '../../../config/FormInputTheme';
import { Structure } from './FormSend';
import useAxios from 'axios-hooks';
import serverPath from '../../../services/serverPath';
import { LoadingButton } from '@mui/lab';
import { getName } from '../../../services/getFileExtension';
import { useSession } from '../../../services/globalConfig';
import { parse } from '../../../services/localStorageData';
import CropText from '../../../components/CropText';

export default function CoverNav (props) {
    const [,{ getSession }] = useSession();
    const {/*id: userId, */ token, } = getSession('user') || {};
    const [{loading, data}, refetch, cancel] = useAxios({
            url: COVER_URL,
            headers: {
                'Authorization': `Bearer ${token}`
            },
        },{ manual: true });
    useEffect(() => {
        if(props.open)
            refetch();
    },[props.open]);
  
    return (
        <Dialog
          open={props.open}
          fullScreen
          onClose={props.onClose}
          
        >
            <Header
                onClose={props.onClose}
                refetch={refetch}
            />
            <Backdrop
                sx={{
                color: '#fff',
                zIndex: theme => theme.zIndex.drawer + 1,
                backdropFilter: 'blur(15px)',
                }}
                open={ data ? false : loading}
            >
                <CircularProgress
                    color="inherit"
                    size="small"
                    sx={{
                        width: 25,
                        height: 25
                    }}
                />
            </Backdrop>
            <Box
                sx={{
                    flex: 1,
                    width: '100%',
                }}
            >
                {
                    !(data?.length) &&
                    <Typography align="center" color="text.secondary">
                        Aucune couverture disponible
                    </Typography>
                }
                {data &&
                <ImageList 
                    cols={10}
                    sx={{ m:1, }}
                >
                {data?.map((cover) => (
                    <ImageListItem 
                    key={cover._id}>
                        <CardActionArea
                            sx={{width: 130,}}
                            onClick={() => {
                                props?.onChange({
                                    coverURL: cover.contentUrl,
                                    ...cover,
                                    contentUrl: undefined,
                                });
                        }}
                        >
                            <CardMedia
                                src={cover.contentUrl}
                                srcSet={cover.contentUrl}
                                alt={cover.name}
                                loading="lazy"
                                component="img"
                                height={160}
                                sx={{
                                    width: 130,
                                }}
                            />
                        </CardActionArea>
                        <ImageListItemBar
                            title={
                                <Typography variant="body2"> 
                                    { cover?.name?.length < 16  ? cover?.name?.toLowerCase() :
                                    <CropText len={16}>{cover?.name?.toLowerCase()}</CropText>}
                                </Typography> 
                            }
                            subtitle={
                            <span>{
                                (() => {
                                    const title = cover.docTypes[0] + (cover.docTypes[1] ? `/${cover.docTypes[1]}` : '');
                                    return (
                                        title?.length < 16  ? title :
                                        <CropText len={16}>{title}</CropText>
                                        )
                                })()
                                
                            }</span>}
                            position="below"
                        />
                    </ImageListItem>
                ))}
                </ImageList>}
            </Box>
        </Dialog>
    )
}

function Header (props) {
    const inputRef = useRef(null);
    const [values, setValues] = useState({
        file: null,
    });

    const handleChange = event => {
        const [file] = event.target.files;
        if(file) setValues({...values, file});
    };

    return (
        <React.Fragment>
            <input ref={inputRef} hidden type="file" accept="image/*" onChange={handleChange}/>
            <FormCover
                file={values.file}
                onClose={() => setValues({
                    ...values, 
                    file: null,
                })}
                refetch={props.refetch}
            />
            <AppBar sx={{ position: 'relative' }}>
                <Toolbar>
                    <Typography sx={{flex: 1 }} variant="h6" component="div">
                        Couvertures des documents
                    </Typography>
                    <Tooltip arrow title="sortir" enterDelay={700}>
                        <IconButton
                            size="small"
                            color="inherit"
                            onClick={props.onClose}
                        >
                            <ExitToAppRoundedIcon fontSize="small"/>
                        </IconButton>
                    </Tooltip>
                </Toolbar>
            </AppBar>
            <Stack direction="row" spacing={1} sx={{bgcolor: 'background.paper', p: 1}}>
                <Button 
                    children="Ajouter une image de couverture depuis votre appareil ..."
                    size="small"
                    sx={{
                        textTransform: 'none'
                    }}
                    onClick={() => inputRef.current?.click()}
                />
            </Stack>
        </React.Fragment>
    )
}

function FormCover (props) {
    const [{loading}, refetch, cancel] = useAxios(COVER_URL, {
        manual: true,
    });
    const defaultName = getName(props?.file?.name || '');
    const [,{ getSession }] = useSession();
    const {/*id: userId, */ token, } = getSession('user') || {};
    const [values, setValues] = useState({
        checking: [],
    });

    const dataFile = {
        doc: useRef(''),
        subDoc: useRef(''),
        name: useRef(defaultName),
    };
    const handleCancel = event => {
        event?.preventDefault();
        cancel();
        props?.onClose();
    }
   // console.log(dataFile);
    const handlerSend = event => {
        event?.preventDefault();
        const data = new FormData();
        let errors = [];
        Object.keys(dataFile).forEach(field => {
            if(!dataFile[field].current)
                errors.push(field);
            if(field === 'subDoc') 
            errors = dataFile[field]?.current === null ? 
            errors.map(field => field !== 'subDoc' && field)
            .filter(field => field) : errors;
        });
        data.append('name',  dataFile.name.current || defaultName);
        data.append('docTypes',
            parse([
                dataFile.doc.current, 
                dataFile.subDoc.current,
            ].filter(e => e))
        );
        data.append('file', props.file);
        if(errors.length)
            setValues({checking: errors});
        else
            refetch({
                data,
                method: 'post',
                headers: {
                    'Authorization': `Bearer ${token}`
                },
            }).then( () => {
                props?.refetch();
                props?.onClose();
            }).catch(error => {
                console.log(error);
            });
    };

    return (
        <Dialog
            open={!!props.file}
        >
            <DialogContent sx={{
                width: 500
            }}>
                <Stack direction="row" spacing={1}>
                    <Box sx={{flexGrow: 1}}>
                        <Grid container spacing={1}>
                            <Box item xs={12} component={Grid}>
                                <TextFieldController
                                    margin="dense"
                                    label="Nom du couverture"
                                    fullWidth
                                    size="small"
                                    defaultValue={defaultName}
                                    ref={dataFile.name}
                                    checking={!!~values.checking.indexOf('name')}
                                    regExp={".+"}
                                />
                            </Box>
                            <Structure
                                refs={{
                                    doc: dataFile.doc,
                                    subDoc: dataFile.subDoc,
                                }}
                                checking={values.checking}
                            />
                        </Grid>
                    </Box>
                    <Box>
                        <Card>
                            <CardMedia
                                component="img"
                                height={200}
                                src={props.file && URL.createObjectURL(props.file)}
                                sx={{
                                    height: 150,
                                    width: 120,
                                }}
                            />
                        </Card>
                    </Box>
                </Stack>
            </DialogContent>
            <FormInputTheme>
                <DialogActions>
                    <Button
                        size="small"
                        children="annuler"
                        onClick={handleCancel}
                    />
                    <LoadingButton
                        size="small"
                        children="ajouter"
                        variant="outlined"
                        onClick={handlerSend}
                        loading={loading}
                    />
                </DialogActions>
            </FormInputTheme>
        </Dialog>
    );
}

const COVER_URL = serverPath('api/stuff/cover');
